INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2326', 'spa', 'Cosecha, siega; el acto de segar, la temporada de cosecha o el fruto recogido, frecuentemente usado en sentido figurado para referirse a la recolecció', 'Cosecha, siega; el acto de segar, la temporada de cosecha o el fruto recogido, frecuentemente usado en sentido figurado para referirse a la recolección final de Dios. Se refiere a la siega del grano: la estación, el acto o la mies recogida. En el mundo agrícola de la Palestina del siglo primero, la cosecha era el momento culminante del año agrícola, y los escritores del NT aprovechan plenamente esta resonancia. Jesús lo emplea literalmente cuando dice «la mies es mucha, mas los obreros pocos» (Mt 9:37-38; Lc 10:2), aunque incluso allí la metáfora de la recolección evangelística es inconfundible. En la parábola del trigo y la cizaña (Mt 13:30, 39), la cosecha se convierte en imagen explícita del juicio final. Apocalipsis 14:15 lleva la metáfora a su conclusión apocalíptica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2328', 'spa', 'Calentarse o ser calentado; se usa para el acto físico de calentarse junto al fuego y para la necesidad básica de calor corporal.', 'Verbo sencillo pero narrativamente poderoso en el Nuevo Testamento. Sus apariciones más memorables ocurren durante la negación de Pedro, quien permanece calentándose junto al fuego de carbón en el patio del sumo sacerdote (Mr 14:54, 67; Jn 18:18, 25). El participio repetido «calentándose» funciona casi como un estribillo que subraya la cercanía vulnerable de Pedro al peligro. En Santiago 2:16 el verbo cambia de registro para desenmascarar la religión vacía: decir «calentaos y saciaos» sin suplir la necesidad real es fe sin obras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2329', 'spa', 'Calor, calidez; alta temperatura; calor febril o energía térmica.', 'Este sustantivo denota calor o calidez, ya sea del sol, del fuego o de la fiebre. En el uso clásico se aplicaba al clima caluroso, al calor febril y a la energía térmica. Lucas lo emplea en Hechos para describir el calor que hizo salir a una víbora de la leña que Pablo estaba recogiendo. El término enfatiza la sensación física y el efecto del calor. Podía describir tanto la calidez beneficiosa como el calor abrasador y peligroso. Los escritores médicos griegos lo usaban para fiebres y condiciones inflamatorias. La palabra capta el calor como fenómeno natural y como peligro potencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2330', 'spa', 'verano, la estación cálida; también tiempo de cosecha o frutos estivales', 'Este sustantivo designa el verano, la estación entre la primavera y el otoño. Las tres ocurrencias aparecen en la parábola de la higuera que retoña, señalando que «el verano está cerca». Jesús emplea esta observación natural como paralelo de las señales escatológicas en el Discurso del Monte de los Olivos (Mateo 24:32, Marcos 13:28, Lucas 21:30). El uso clásico incluye el verano como temporada de campañas militares, tiempo de cosecha, frutos estivales e incluso, metafóricamente, la plenitud de la juventud. En el Nuevo Testamento el uso es estrictamente estacional y literal: la transición reconocible de la primavera al verano como analogía para discernir la proximidad del reino de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2331', 'spa', 'Tesalonicense; habitante o natural de Tesalónica, capital de la provincia romana de Macedonia', 'Este gentilicio identifica a alguien originario de Tesalónica, la bulliciosa ciudad portuaria y capital de la Macedonia romana. Los compañeros de viaje de Pablo, Aristarco y Segundo, son llamados tesalonicenses (Hch 20:4; 27:2), y ambas cartas canónicas dirigidas a la iglesia de esa ciudad se abren saludando a la congregación como ''los tesalonicenses'' (1 Ts 1:1; 2 Ts 1:1). El término se translitea de forma consistente en todos los idiomas, reflejando su carácter de nombre propio como designación étnico-geográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2332', 'spa', 'Tesalónica; importante ciudad macedónica, centro de la misión de Pablo y sede de una iglesia primitiva clave', 'Nombre propio de la capital de la provincia romana de Macedonia, la actual Salónica. Era una próspera ciudad portuaria sobre la Vía Egnatia donde Pablo fundó una iglesia durante su segundo viaje misionero. La ciudad aparece en momentos decisivos: la fundación de la congregación (Hch 17:1), la respuesta contrastante de los bereanos (Hch 17:11), la oposición que persiguió a Pablo hasta Berea (Hch 17:13), la generosidad de los filipenses enviada a Pablo mientras estaba allí (Fil 4:16) y la partida de Demas hacia Tesalónica (2 Tim 4:10).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2333', 'spa', 'Teudas, nombre propio; posiblemente contraído de Teodoro; revolucionario judío mencionado en Hechos.', 'Este nombre, posiblemente una forma abreviada de Teodoro (''don de Dios''), identifica a un revolucionario fracasado mencionado por Gamaliel en Hechos. Según el discurso de Gamaliel, Teudas afirmó ser alguien importante, atrajo a unos cuatrocientos seguidores, pero fue ejecutado y su movimiento se dispersó. La identificación histórica es debatida, ya que Josefo menciona a un Teudas activo en fecha posterior a este discurso. El nombre sirve al argumento de Gamaliel de que si el movimiento de los apóstoles no proviene de Dios, fracasará igualmente. Como muchos nombres bíblicos, ofrece una breve ventana al turbulento panorama político de la Judea del siglo primero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2334', 'spa', 'Ver, contemplar, observar; percepción visual que va desde la simple vista hasta la contemplación atenta', 'Derivado de θεωρός (''espectador''), este verbo conlleva un matiz de visión comprometida: no una mirada casual, sino una contemplación que asimila lo que tiene delante. En los Evangelios describe desde presenciar el sepulcro vacío (Mc 16:4) hasta las mujeres que observan la crucifixión desde lejos (Mt 27:55; Mc 15:40). El español ''contemplar'' capta con precisión esa cualidad contemplativa que distingue a θεωρέω de verbos más simples como βλέπω u ὁράω. En Hebreos 7:4 la observación se vuelve intelectual: ''Considerad cuán grande era este hombre''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2335', 'spa', 'Espectáculo, escena pública, representación; algo observado o contemplado; exhibición o función teatral.', 'Este sustantivo designa un espectáculo o escena: algo que se observa, ya sea un evento público, una representación teatral o una escena notable. En el uso clásico incluía embajadas religiosas a festivales, asistencia a juegos o al teatro, y el acto general de contemplar. Lucas lo emplea para describir a las multitudes que regresaban de la crucifixión de Jesús tras presenciar el espectáculo. El término puede enfatizar tanto lo que se observa como el acto mismo de observarlo. Está emparentado con θεωρέω (mirar, contemplar) y θεατρίζω (exhibir públicamente), compartiendo la raíz semántica de ver o ser visto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2336', 'spa', 'Vaina, funda, estuche; recipiente para una espada u otra arma.', 'Este sustantivo designa una vaina o funda, particularmente para una espada. En el uso clásico se extendía a cualquier recipiente: un cofre, una tumba o un estuche para arco. Juan lo emplea en la escena del arresto en el huerto cuando Jesús le ordena a Pedro que vuelva a poner su espada en la vaina. El término enfatiza el lugar de reposo de la espada, donde pertenece cuando no está en uso. Los textos clásicos lo usaban para contenedores de armas e incluso metafóricamente para las tumbas como ''estuche'' del cuerpo. El uso neotestamentario es directo: la cubierta protectora que sostiene la hoja cuando está enfundada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2337', 'spa', 'Amamantar, dar de mamar; dar el pecho o mamar del pecho materno', 'Verbo que abarca ambos lados de la relación de lactancia: la madre que da de mamar y el bebé que mama. En el Nuevo Testamento aparece en momentos profundamente humanos: Jesús citando el Salmo 8 sobre la alabanza de los lactantes (Matt 21:16), advertencias sobre la dificultad especial que enfrentarán las madres lactantes en tiempos de crisis (Matt 24:19; Mark 13:17; Luke 21:23), y la bendición de una mujer sobre los pechos que amamantaron a Jesús (Luke 11:27). El español distingue bien entre ''amamantar'' (dar el pecho) y ''mamar'' (tomar leche del pecho), reflejando la capacidad del verbo para expresar tanto la perspectiva de la madre como la del niño.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2338', 'spa', 'Femenino; perteneciente al sexo femenino, usado de personas y animales en contraste con el masculino', 'Derivado de la raíz que significa ''amamantar'', este adjetivo designa el sexo femenino en distinción del masculino. En el Nuevo Testamento aparece en declaraciones fundamentales sobre la creación de la humanidad como ''varón y hembra'' (Matt 19:4; Mark 10:6) y en la visión paulina de igualdad en Cristo donde ''no hay varón ni hembra'' (Gal 3:28). También describe el intercambio antinatural de las relaciones femeninas en Rom 1:26-27. Su sentido biológico directo se traduce de manera consistente al español como ''hembra''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2339', 'spa', 'Caza, cacería, persecución; la captura de una presa; metafóricamente, trampa o lazo.', 'Este sustantivo denota la caza: la persecución, captura y matanza de presas. Puede referirse tanto a la actividad en sí como a la presa capturada. En el uso clásico abarcaba la caza de animales salvajes, la cetrería y la pesca. Metafóricamente, describía la persecución ávida de cualquier cosa o de alguien como presa. Pablo lo emplea figuradamente en Romanos, citando los Salmos, para describir cómo la mesa de los impíos se convierte en trampa o lazo. La imagen cinegética sugiere que algo aparentemente beneficioso, un banquete, se transforma en un instrumento de captura y destrucción. El término abarca tanto la persecución activa como los medios de atrapamiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2340', 'spa', 'Cazar, atrapar, perseguir una presa; tender una trampa; metafóricamente, buscar atrapar a alguien en sus palabras.', 'Este verbo significa cazar o atrapar una presa, ya sean animales en la caza literal o personas en un atrapamiento metafórico. En el uso clásico cubría la caza de bestias salvajes, la captura de aves o peces, y la persecución de cualquier presa. Lucas lo emplea metafóricamente para describir a los escribas y fariseos que acechaban para atrapar a Jesús en sus palabras, cazándolo verbalmente en busca de evidencia acusatoria. El verbo expresa la persecución activa e intencional con el objetivo de capturar y destruir a la presa. Como un cazador al acecho, los oponentes de Jesús buscaban oportunidades para atraparlo en declaraciones que pudieran usar en su contra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2341', 'spa', 'Luchar con fieras, combatir contra bestias salvajes en la arena; metafóricamente, enfrentar oponentes feroces.', 'Este verbo describe el combate con animales salvajes, particularmente en el contexto de los espectáculos de la arena romana, donde personas condenadas o gladiadores enfrentaban leones, osos u otras bestias. La referencia de Pablo en 1 Corintios emplea esta imagen, ya sea de peligro literal o de oposición metafórica, lo cual sigue en debate, para transmitir la ferocidad de sus luchas en Éfeso. Las glosas multilingües enfatizan consistentemente el aspecto de la lucha contra fieras, preservando la construcción literal de ''luché con fieras'' que abarca ambos significados posibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2342', 'spa', 'Bestia o animal salvaje; en el NT predominantemente la Bestia apocalíptica de Apocalipsis, pero también cualquier criatura peligrosa o salvaje', 'Bestia o animal salvaje; en el NT predominantemente la Bestia apocalíptica de Apocalipsis, pero también cualquier criatura peligrosa o salvaje');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2343', 'spa', 'Atesorar, almacenar o guardar; usado para acumular riquezas, provisiones o consecuencias divinas', 'Derivado de θησαυρός (''tesoro, almacén''), este verbo significa acumular o guardar para uso futuro. Jesús contrasta el atesorar tesoros en la tierra frente al cielo (Mt 6:19-20), estableciendo la tensión teológica central del término. Pablo advierte sobre ''atesorar ira'' para el día del juicio (Ro 2:5), invirtiendo la connotación positiva en algo ominoso, mientras Santiago acusa a los ricos que han ''acumulado tesoros en los últimos días'' (Stg 5:3). La instrucción a los corintios de apartar contribuciones semanalmente (1 Co 16:2) mantiene el vocablo anclado en la economía cotidiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2344', 'spa', 'Tesoro, riqueza acumulada; un depósito o repositorio de cosas valiosas, ya sean materiales o espirituales. θησαυρός designa tanto el tesoro en sí como', 'Tesoro, riqueza acumulada; un depósito o repositorio de cosas valiosas, ya sean materiales o espirituales. θησαυρός designa tanto el tesoro en sí como el lugar donde se guarda: un almacén o tesorería. Jesús lo usa en el Sermón del Monte para contrastar el tesoro terrenal, vulnerable a la polilla y la herrumbre, con el tesoro imperecedero en el cielo (Mt 6:19-21). También habla del corazón como un θησαυρός del cual fluye lo bueno o lo malo (Mt 12:35; Lc 6:45). Los magos abren sus cofres de tesoros ante el niño Cristo (Mt 2:11). Pablo habla de los ''tesoros de sabiduría y conocimiento'' escondidos en Cristo (Col 2:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2345', 'spa', 'tocar, palpar, asir; tener contacto físico con algo o alguien', 'Este verbo significa tocar, palpar o asir algo o a alguien. Aparece en tres contextos significativos de prohibición. Colosenses 2:21 cita las reglas de falsos maestros: «No manejes, ni gustes, ni toques». Hebreos 11:28 describe cómo la Pascua protegió a Israel para que el destructor «no tocase» a los primogénitos. Hebreos 12:20 evoca la teofanía del Sinaí, donde incluso un animal que tocase el monte debía morir. El uso clásico abarca desde el simple contacto hasta el agarre, el abrazo y, eufemísticamente, el contacto sexual. En el Nuevo Testamento el énfasis recae en el contacto prohibido o peligroso: tabúes legalistas, juicio divino o límites sagrados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2346', 'spa', 'De una raíz que significa ''presionar'' o ''apretar'', este verbo abarca desde el acto físico de agolparse hasta el profundo concepto teológico de la trib', 'De una raíz que significa ''presionar'' o ''apretar'', este verbo abarca desde el acto físico de agolparse hasta el profundo concepto teológico de la tribulación. Marcos 3:9 lo emplea en sentido literal: la multitud presiona contra Jesús con tal fuerza que él pide una barca. Pablo lo transforma en sello distintivo de la existencia apostólica: ''atribulados en todo, mas no angustiados'' (2 Co 4:8), y ''cuando llegamos a Macedonia, ningún reposo tuvo nuestro cuerpo, sino que en todo fuimos atribulados'' (2 Co 7:5). De modo memorable, Jesús usa el participio perfecto pasivo en Mateo 7:14 para describir el camino que lleva a la vida como ''angosto'', literalmente comprimido por ambos lados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2347', 'spa', 'tribulación, aflicción, angustia — presión por adversidades externas, persecución o prueba escatológica', 'tribulación, aflicción, angustia — presión por adversidades externas, persecución o prueba escatológica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2348', 'spa', 'Haber muerto, estar muerto; perfecto de θνῄσκω que enfatiza el evento consumado con su resultado vigente', 'Todas las apariciones neotestamentarias de θνῄσκω se dan en tiempo perfecto, lo cual confiere a este verbo un perfil inconfundible: no describe el acto de morir sino el estado consumado de estar muerto. Cuando el ángel dice a José que quienes buscaban la vida del niño ''han muerto'' (Mt 2:20), o cuando Pilato se asombra de que Jesús ''ya hubiera muerto'' (Mc 15:44), la gramática subraya la finalidad. La misma construcción aparece en los relatos de resurrección del hijo de la viuda (Lc 7:12), la hija de Jairo (Lc 8:49) y Lázaro (Jn 11:44), donde el perfecto intensifica el milagro: estas personas estaban definitivamente muertas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2349', 'spa', 'Mortal, sujeto a la muerte; describe el cuerpo humano como inherentemente perecedero, en contraste con la vida imperecedera.', 'Adjetivo que significa ''sujeto a la muerte'' o ''mortal'', usado en el NT exclusivamente para referirse al cuerpo humano, subrayando su vulnerabilidad y el poder transformador de la resurrección. Pablo ordena a los creyentes no dejar que el pecado reine en su ''cuerpo mortal'' (Rom 6:12), promete que el Espíritu que resucitó a Jesús vivificará sus ''cuerpos mortales'' (Rom 8:11), y en el gran capítulo de la resurrección declara que ''esto mortal debe vestirse de inmortalidad'' (1 Cor 15:53-54). En 2 Cor 4:11, la vida de Jesús se manifiesta en ''nuestra carne mortal''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2350', 'spa', 'Causar alboroto, producir conmoción; estar turbado, angustiado o agitado interiormente', 'Este verbo capta tanto el ruido externo como la agitación interior. Puede describir multitudes que producen una perturbación clamorosa, como cuando las plañideras profesionales lloran en la casa de Jairo (Matt 9:23; Mark 5:39) o cuando una turba se subleva en Tesalónica (Acts 17:5). Pero también conlleva un sentido interno de agitación ansiosa, como cuando Jesús le dice a Marta que está ''afanada y turbada'' por muchas cosas (Luke 10:41). Las traducciones al español se dividen claramente entre el alboroto externo (''alborotaban'') y la alarma interna (''os alarmeis''), revelando este doble rango semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2351', 'spa', 'Alboroto, tumulto o conmoción; el ruido confuso y la agitación de una multitud, a menudo con matices políticos u hostiles.', 'En el Nuevo Testamento, θόρυβος describe la energía volátil de una multitud que puede desembocar en disturbio. Los sumos sacerdotes temen un alboroto si arrestan a Jesús durante la fiesta (Mt 26:5; Mc 14:2), y Pilato ve cómo se forma uno (Mt 27:24). En Mc 5:38, la misma palabra describe el llanto ruidoso en la casa de Jairo, una conmoción nacida del duelo y no de la hostilidad. El término abarca desde el disturbio político hasta la agitación doméstica por el dolor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2352', 'spa', 'Romper, quebrantar o aplastar; metafóricamente, oprimir o quebrantar el espíritu de alguien', 'El verbo θραύω abarca sentidos tanto físicos como metafóricos de romper o quebrantar. En su uso literal, describe la acción de hacer pedazos objetos como cerámica, roca o alas. Los autores clásicos lo emplearon en sentido figurado para referirse a destruir la esperanza, aplastar el ánimo o debilitar las fuerzas. En Lucas 4:18, Jesús cita a Isaías usando el participio perfecto pasivo para describir a los «oprimidos» o «quebrantados», refiriéndose a los abatidos y de espíritu roto. La imagen transita de lo físico a lo espiritual y social, capturando la condición de quienes necesitan liberación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2353', 'spa', 'Criatura alimentada o criada; animales domésticos, especialmente rebaños de ovejas y cabras; ganado', 'El sustantivo θρέμμα (derivado de τρέφω, «alimentar/nutrir») significaba originalmente cualquier criatura alimentada o lactante, pero pasó a referirse especialmente a animales domésticos como ovejas, cabras y vacas. Los autores antiguos lo usaban para animales mansos en contraste con las bestias salvajes, y en ocasiones lo extendían metafóricamente a esclavos domésticos («criados en casa»). En Juan 4:12, la mujer samaritana pregunta si Jesús es mayor que Jacob, quien dio el pozo y cuyos ganados (θρέμματα) bebían de él. Las traducciones lo vierten uniformemente como ganado o rebaños.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2354', 'spa', 'Lamentarse, plañir o entonar un canto fúnebre; lamento vocal ritualizado por los muertos o por el duelo', 'Derivado del sustantivo θρῆνος (canto fúnebre), este verbo designa el lamento formal y vocal propio de los funerales y las expresiones públicas de duelo. Jesús lo emplea en la parábola de los niños en la plaza que se quejan: ''les cantamos endechas y no lamentasteis'' (Mt 11:17; Lc 7:32), subrayando la respuesta social esperada ante la muerte. Las mujeres del camino al Calvario θρηνέω por Jesús (Lc 23:27), y él advierte a los discípulos que su dolor será real mientras el mundo se alegra (Jn 16:20). El español ''lamentar'' y ''plañir'' captan la cualidad sostenida y vocal de este tipo de duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2355', 'spa', 'endecha, lamentación; canto fúnebre o de duelo', 'Canto formal de duelo o lamentación, entonado típicamente en funerales o en tiempos de desastre. Homero y los poetas clásicos emplean el término para las endechas rituales que acompañan a la muerte. Píndaro compuso θρῆνοι como género literario diferenciado. La palabra también puede significar queja o tonada triste en sentido más amplio: cualquier canción lastimera o expresión de dolor. En contextos bíblicos describe los cantos fúnebres por los muertos y las lamentaciones proféticas sobre ciudades o naciones. Las Lamentaciones de Jeremías ejemplifican este género. El sustantivo deriva de un verbo que significa gemir o clamar, capturando la intensidad vocal de los antiguos ritos de duelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2356', 'spa', 'Culto religioso, piedad o práctica devocional; la expresión externa de la religión, ya sea genuina o meramente formal', 'Este sustantivo abarca todo el espectro de la observancia religiosa, desde la devoción sincera hasta el ritual vacío. Pablo lo usa para referirse a su vida anterior en la secta más estricta del judaísmo (Hch 26:5), mientras que Santiago contrasta célebremente la θρησκεία vana — meras palabras — con la ''religión pura y sin mancha'' que cuida de huérfanos y viudas (Stg 1:26-27). Colosenses 2:18 advierte contra una θρησκεία de ángeles, un culto desviado dirigido a seres intermediarios. La palabra puede ser positiva o negativa según si la adoración está bien orientada y se vive con autenticidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2357', 'spa', 'Religioso, devoto; dado a la observancia religiosa (puede tener sentido negativo de supersticioso)', 'Este adjetivo describe a alguien entregado a la práctica y observancia religiosa. Si bien es generalmente positivo («devoto», «piadoso»), también puede inclinarse hacia el sentido negativo de «supersticioso» o excesivamente escrupuloso con los rituales. Santiago 1:26 lo usa para quien «se cree religioso»; el contexto sugiere una práctica religiosa exterior que puede carecer de contenido ético auténtico (controlar la lengua, cuidar de los huérfanos). Aunque aparece raramente en los textos bíblicos, su ambivalencia entre devoción genuina y mera religiosidad lo hace idóneo para la advertencia de Santiago contra el autoengaño en la observancia religiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2359', 'spa', 'Cabello, pelo; referido principalmente al cabello humano de la cabeza, y también al pelo animal (pelo de camello) usado como material para vestimenta.', 'Cabello, pelo; referido principalmente al cabello humano de la cabeza, y también al pelo animal (pelo de camello) usado como material para vestimenta. θρίξ es un sustantivo físico sencillo que designa el cabello, pero en el NT desempeña funciones sorprendentemente ricas. El cabello humano aparece en dichos proverbiales sobre el cuidado soberano de Dios («los cabellos de vuestra cabeza están todos contados», Mt 10:30; Lc 12:7) y en actos íntimos de devoción cuando María seca los pies de Jesús con su cabello (Lc 7:38, 44; Jn 11:2; 12:3). La palabra también describe la vestimenta áspera de Juan el Bautista «de pelo de camello» (Mt 3:4; Mr 1:6), y en Apocalipsis 1:14 y 9:8 el cabello sirve como marca de apariencia e identidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2360', 'spa', 'Alarmarse, perturbarse, agitarse por temor; ser sacudido emocionalmente ante una crisis', 'Este verbo, usado en voz pasiva en el Nuevo Testamento, describe el estado de alarmarse, asustarse o agitarse a causa del temor. Aparece en contextos escatológicos donde Jesús advierte contra el pánico: en Mateo 24:6 y Marcos 13:7 dice «no os alarméis» al oír de guerras y rumores de guerras. En 2 Tesalonicenses 2:2, Pablo exhorta a los creyentes a no dejarse perturbar por falsas afirmaciones sobre la llegada del día del Señor. En todos los casos neotestamentarios se trata de una agitación emocional basada en el miedo, frente a la cual se requiere fe serena en medio del tumulto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2361', 'spa', 'Coágulo, grumo o gota espesa; especialmente coágulos de sangre o gotas grandes que caen como grumos', 'El sustantivo θρόμβος significa literalmente un grumo o coágulo, usado en textos médicos para coágulos de sangre y en contextos agrícolas para cuajadas de leche o sal gruesa. El sentido de «gota» surgió para gotas grandes y pesadas que caen como grumos, no como rocío fino. El Evangelio de Lucas emplea el plural para describir el sudor de Jesús en Getsemaní cayendo «como grandes gotas de sangre» (Lucas 22:44). La comparación no sugiere color sino la naturaleza densa y pesada de la transpiración. Las traducciones lo vierten como «gotas», aunque la imagen subyacente es de gotas espesas y coaguladas, no gotitas finas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2362', 'spa', 'θρόνος — trono, sede de autoridad real o divina; tanto el asiento físico como la soberanía que representa', 'El sustantivo masculino θρόνος (''trono'') designa un asiento de autoridad real o divina: tanto la silla de estado como, por metonimia, el poder soberano que representa. Sus 63 apariciones neotestamentarias son abrumadoramente teológicas: el trono de Dios en el cielo (Mt 5:34; Ap 4:2-6), el trono escatológico de gloria de Cristo (Mt 25:31), los doce tronos de los apóstoles (Mt 19:28) y el trono dinástico de David heredado por el Mesías (Lc 1:32; Hch 2:30). Solo Apocalipsis concentra casi la mitad de las ocurrencias, desplegando la sala del trono celestial en vívida imaginería apocalíptica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2363', 'spa', 'Tiatira; ciudad de la antigua Lidia en Asia Menor occidental, conocida por sus gremios comerciales y su industria de tinte púrpura', 'Ciudad de la región de Lidia en Asia Menor, Tiatira era famosa por sus gremios comerciales y especialmente por su industria del tinte púrpura, el mismo oficio que ejercía Lidia, la primera conversa europea de Pablo (Hch 16:14). En Apocalipsis es la cuarta de las siete iglesias a las que se dirige, recibiendo tanto elogio por sus obras crecientes como una severa reprensión por tolerar a la falsa profetisa ''Jezabel'' (Ap 2:18-24). El nombre se translitea uniformemente en español como ''Tiatira.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2364', 'spa', 'Hija; una mujer joven, descendiente o miembro de una comunidad a quien se dirige con calidez familiar.', 'Hija; una mujer joven, descendiente o miembro de una comunidad a quien se dirige con calidez familiar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2366', 'spa', 'Huracán, tormenta violenta o torbellino; tempestad con viento impetuoso y arrasador', 'El sustantivo θύελλα describe perturbaciones atmosféricas violentas: huracanes, torbellinos o tormentas severas caracterizadas por viento impetuoso y destructivo. Homero lo empleó para imágenes de tormenta en batalla y tempestades destructivas en el mar. La palabra enfatiza la cualidad violenta e impetuosa del viento, más que simplemente lluvia o truenos. Hebreos 12:18 contrasta la aterradora teofanía del Sinaí («tiniebla, oscuridad y tempestad») con la cercanía accesible del nuevo pacto. Las traducciones lo vierten uniformemente como «tempestad» o «tormenta», capturando el fenómeno meteorológico temible que simboliza la alteridad y el poder divinos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2367', 'spa', 'hecho de madera de cidro (tuya); relativo a la madera aromática y costosa de árboles norteafricanos', 'Este adjetivo describe objetos fabricados con la madera del árbol θύον, una conífera aromática del norte de África (probablemente Tetraclinis articulata, conocida como cidro o sándalo africano). Las fuentes antiguas apreciaban esta madera por su veta hermosa, aroma agradable y gran durabilidad, empleándola en muebles lujosos y objetos decorativos. Apocalipsis 18:12 incluye la «madera de tuya» entre las mercancías suntuarias que ya nadie compra en la Babilonia caída. Las traducciones varían entre «cidro», «olorosa» y «Zitrusholz», reflejando la incertidumbre sobre la identidad botánica exacta, pero preservando el sentido de madera rara, aromática y valiosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2368', 'spa', 'Incienso; sustancia aromática quemada como ofrenda sagrada, cuyo humo fragante asciende ante Dios.', 'Se refiere al material aromático que se quema en el culto, produciendo un humo que se eleva simbólicamente hacia el cielo. En el contexto del Templo de Lc 1:10-11, toda la asamblea ora afuera mientras Zacarías quema incienso en el altar, momento en que un ángel aparece para anunciar el nacimiento de Juan. En Apocalipsis, el incienso adquiere un rico simbolismo: las copas de oro llenas de incienso representan las oraciones de los santos (Ap 5:8), y un ángel ofrece mucho incienso junto con las oraciones sobre el altar de oro ante el trono (Ap 8:3-4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2369', 'spa', 'incensario, altar del incienso o recipiente para quemar incienso; instrumento para ofrecer humo aromático', 'El sustantivo θυμιατήριον designa un instrumento para quemar incienso, ya sea un incensario portátil (quemador manual) o un altar de incienso. Las fuentes clásicas lo emplean tanto para censers usados en rituales del templo como para recipientes de fumigación. Hebreos 9:4 describe los enseres del Lugar Santísimo del tabernáculo, mencionando el «incensario de oro» o «altar de oro del incienso» junto al arca. Si se refiere a un incensario portátil o al altar del incienso —que normalmente se ubicaba fuera del velo— ha sido objeto de debate. Las traducciones reflejan esta ambigüedad léxica: «altar of incense» en inglés, «incensario» en español y francés.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2370', 'spa', 'quemar incienso, ofrecer incienso como acto ritual; hacer subir humo aromático como ofrenda', 'Este verbo describe el acto ritual de quemar incienso, haciendo que el humo aromático se eleve como ofrenda. En el culto del templo, los sacerdotes quemaban incienso sobre el altar, produciendo humo fragante que simbolizaba las oraciones ascendiendo hacia Dios. El verbo puede usarse transitivamente (quemar algo como incienso) o de forma absoluta (realizar el rito del incienso). Lucas 1:9 relata que Zacarías fue elegido por sorteo para «quemar incienso» al entrar en el santuario del templo, un privilegio excepcional en la vida de un sacerdote. Las traducciones preservan uniformemente la acción ritual: «quemar incienso», «brûler de l''encens», subrayando la sacralidad de la ofrenda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2371', 'spa', 'estar furiosamente enojado, enfurecerse; pelear con ira intensa u hostilidad violenta', 'El verbo θυμομαχέω combina θυμός (ira, pasión) con μάχομαι (pelear), describiendo a alguien que lucha con furia o se involucra en una contienda hostil. Las fuentes antiguas lo emplean para peleas desesperadas o disputas obstinadas impulsadas por la rabia. Hechos 12:20 describe a Herodes como «furiosamente enojado» (θυμομαχῶν) contra los habitantes de Tiro y Sidón, quienes acuden a buscar la paz. El participio sugiere que Herodes se encontraba en un estado de hostilidad iracunda hacia esas ciudades. Las traducciones captan la agresividad intensa: «furiously angry», «furioso», «furieux».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2372', 'spa', 'Ira, furor, rabia apasionada: enojo intenso, especialmente el juicio escatológico divino en Apocalipsis. θυμός denota una ira ardiente y feroz, la emo', 'Ira, furor, rabia apasionada: enojo intenso, especialmente el juicio escatológico divino en Apocalipsis. θυμός denota una ira ardiente y feroz, la emoción intensa que en el griego clásico se ubicaba en el pecho como la parte fogosa del alma. De sus 18 apariciones en el NT, más de la mitad se encuentran en Apocalipsis, donde se convierte en el término emblemático para la furia divina derramada en los últimos días. ''El vino de la ira (θυμός) de Dios'' llena la copa del juicio (Ap 14:8, 10, 19; 15:1, 7; 16:1, 19; 18:3; 19:15). Fuera de Apocalipsis, la palabra capta la rabia humana espontánea: la multitud furiosa en Nazaret que intenta arrojar a Jesús por un precipicio (Lc 4:28), la multitud efesia que clama por Artemisa (Hch 19:28). Pablo incluye θυμός entre las obras de la carne junto con la contienda, los celos y la ambición egoísta (Gá 5:20; 2 Co 12:20; Ef 4:31; Col 3:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2373', 'spa', 'airarse, enfurecerse, llenarse de ira; montar en cólera', 'El verbo θυμόω significa provocar ira o, en sus formas media y pasiva, enfurecerse o llenarse de cólera. El sustantivo θυμός denota ira apasionada o furia, y este verbo describe el acto de entrar en ese estado emocional. Puede referirse tanto a la ira humana como a la divina, y las fuentes clásicas también lo emplean para animales salvajes que se agitan. Mateo 2:16 relata la reacción de Herodes al darse cuenta de que los magos lo habían burlado: «se enfureció» (ἐθυμώθη). El aoristo pasivo sugiere que fue invadido por la furia, lo que desencadenó la horrenda matanza de los niños varones de Belén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2374', 'spa', 'Puerta o entrada; abertura para ingresar, usada literalmente de edificios y figuradamente de oportunidad o acceso', 'Puerta o entrada; abertura para ingresar, usada literalmente de edificios y figuradamente de oportunidad o acceso');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2375', 'spa', 'escudo grande oblongo (en forma de puerta); el scutum romano usado por la infantería pesada', 'El sustantivo θυρεός significa literalmente «semejante a una puerta» (de θύρα, puerta) y designa el escudo grande oblongo que cubría casi todo el cuerpo, distinguiéndolo del escudo redondo más pequeño (ἀσπίς). El scutum romano, arma defensiva principal de la infantería pesada, corresponde a esta descripción. En Efesios 6:16, Pablo exhorta a los creyentes a tomar «el escudo de la fe», empleando θυρεός para recalcar una protección integral que cubre a la persona entera. La imagen se apoya en la práctica militar romana bien conocida por los destinatarios de la epístola. Las traducciones lo vierten uniformemente como «escudo», entendiéndose el tipo grande que protege todo el cuerpo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2377', 'spa', 'Portero o portera; persona que vigila y controla el acceso por una puerta o entrada', 'Este sustantivo designa a la persona que monta guardia en una puerta o portón, controlando quién entra y quién no. En la parábola del amo ausente, al portero se le encarga permanecer alerta (Mr 13:34). En el discurso del Buen Pastor de Juan, el θυρωρός abre la puerta al verdadero pastor (Jn 10:3). De modo más conmovedor, una θυρωρός femenina en el patio del sumo sacerdote deja entrar a Pedro y luego lo identifica como discípulo (Jn 18:16-17). El español distingue ''portero'' y ''portera,'' reflejando la flexibilidad de género que el sustantivo griego posee naturalmente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2378', 'spa', 'Sacrificio u ofrenda presentada a Dios, abarcando el acto, la víctima y la adoración espiritual.', 'Sacrificio u ofrenda presentada a Dios, abarcando el acto, la víctima y la adoración espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2379', 'spa', 'Altar; estructura elevada para presentar sacrificios y ofrendas a Dios en el culto del templo o celestial.', 'Altar; estructura elevada para presentar sacrificios y ofrendas a Dios en el culto del templo o celestial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2380', 'spa', 'Sacrificar un animal ritualmente a Dios o a los dioses, o matar/degollar para un festín, o figuradamente para la destrucción. Un verbo enraizado en la', 'Sacrificar un animal ritualmente a Dios o a los dioses, o matar/degollar para un festín, o figuradamente para la destrucción. Un verbo enraizado en la práctica sacrificial antigua que abarca tanto el acto cultual de ofrecer un animal a Dios como el acto más general de degollar para una comida o celebración. Cuando Jesús dice que el ladrón viene para hurtar, matar y destruir (Jn 10:10), la palabra lleva una fuerza letal despojada de todo matiz sagrado. Sin embargo, en Mr 14:12 y Lc 22:7 describe el sacrificio del cordero pascual, un momento litúrgico solemne. La evidencia multilingüe refleja esta división: el español usa «sacrificar» en contextos rituales pero «matar» cuando el énfasis recae en el acto de dar muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2381', 'spa', 'Θωμᾶς (Thōmas) es el nombre propio de uno de los doce apóstoles de Jesús, derivado del arameo תאומא que significa ''gemelo'', traducido al griego como D', 'Θωμᾶς (Thōmas) es el nombre propio de uno de los doce apóstoles de Jesús, derivado del arameo תאומא que significa ''gemelo'', traducido al griego como Dídimo por el Evangelio de Juan (Jn 11:16; 20:24; 21:2). Tomás aparece en cada lista apostólica (Mt 10:3; Mc 3:18; Lc 6:15; Hch 1:13). El Evangelio de Juan le otorga especial protagonismo: declara ''vamos también nosotros, para que muramos con él'' antes de la resurrección de Lázaro (Jn 11:16), pregunta ''Señor, no sabemos a dónde vas'' en la Última Cena (Jn 14:5), y célebremente duda de la resurrección hasta encontrarse con Cristo resucitado, momento en el que pronuncia la confesión culminante ''¡Señor mío y Dios mío!'' (Jn 20:24-28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2382', 'spa', 'Coraza; pieza de armadura defensiva que cubre el pecho, usada en sentido literal y figurado.', 'Este sustantivo designaba originalmente el corsé de bronce de los guerreros griegos, describiendo la armadura que protegía el pecho y el torso. Pablo lo emplea metafóricamente en dos ocasiones: la «coraza de justicia» en el pasaje sobre la armadura espiritual (Eph 6:14) y la «coraza de fe y amor» (1 Thess 5:8). En las visiones apocalípticas de Apocalipsis, las langostas demoníacas llevan corazas semejantes al hierro (Rev 9:9), y la caballería del Éufrates porta corazas de rojo fuego, azul y amarillo sulfúreo (Rev 9:17). La imagen militar concreta se mantiene tanto en el uso literal como en el figurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2384', 'spa', 'Jacob — el patriarca Israel y un antepasado de Jesús en la genealogía de Mateo.', 'Jacob — el patriarca Israel y un antepasado de Jesús en la genealogía de Mateo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2385', 'spa', 'Jacobo (Iakobos) — forma griega de Jacob, llevado por varias figuras del NT incluyendo dos apóstoles', 'Jacobo (Iakobos) — forma griega de Jacob, llevado por varias figuras del NT incluyendo dos apóstoles');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2386', 'spa', 'Sanidad, curación, remedio; el poder o don de sanar como carisma del Espíritu', 'Este sustantivo designa la sanidad o curación, y aparece exclusivamente en la exposición paulina sobre los dones espirituales en 1 Corintios 12. Se menciona tres veces en ese capítulo: dones de sanidades (12:9), los que tienen dones de sanidades (12:28) y la pregunta retórica «¿acaso todos tienen dones de sanidades?» (12:30). El uso constante del plural sugiere diversidad en las manifestaciones del don o múltiples actos de curación. En el Nuevo Testamento su sentido es específicamente carismático: sanidades como manifestaciones del Espíritu para el bien común, distribuidas soberanamente por Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2387', 'spa', 'Jambres, uno de los magos del faraón que se opuso a Moisés (mencionado junto con Janes)', 'Jambres aparece en 2 Timoteo 3:8 como uno de los magos egipcios que resistieron a Moisés, nombrado junto con Janes. Aunque Éxodo 7 no menciona sus nombres, la tradición judía los preservó para identificar a los hechiceros de la corte del faraón que imitaron algunos milagros de Moisés. Pablo los emplea como arquetipos de quienes se oponen a la verdad con mentes corrompidas y una fe falsificada. La mención de estos nombres aparece en diversas fuentes judías y cristianas primitivas, lo que indica una tradición ampliamente conocida. Las traducciones generalmente transliteran el nombre conservando su vínculo con los antagonistas del relato del Éxodo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2388', 'spa', 'Janai, un antepasado de Jesús mencionado en la genealogía de Lucas', 'Janai aparece en Lucas 3:24 como parte de la genealogía que traza el linaje de Jesús desde David hasta Adán. Como muchos nombres en las listas genealógicas, se sabe poco de este individuo más allá de su posición en la ascendencia. El nombre figura únicamente en esta genealogía lucana dentro de los textos bíblicos. La genealogía de Lucas difiere de la de Mateo en varios nombres y en su estructura, reflejando propósitos teológicos distintos y posiblemente tradiciones de linaje diferentes (la línea de José frente a la de María, o descendencia legal frente a biológica). Las traducciones suelen transliterar el nombre manteniendo su carácter de nombre propio sin adiciones interpretativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2389', 'spa', 'Janes, uno de los magos del faraón que se opuso a Moisés (mencionado junto con Jambres)', 'Janes es nombrado junto a Jambres en 2 Timoteo 3:8 como uno de los hechiceros egipcios que resistieron a Moisés. Aunque el relato de Éxodo no conserva sus nombres, la tradición interpretativa judía sí lo hizo, y Pablo recurre a ella para ilustrar la oposición a los mensajeros de Dios. Históricamente, Janes y Jambres reprodujeron los primeros milagros de Moisés mediante artes mágicas antes de verse obligados a reconocer el poder superior de Dios. Pablo los emplea tipológicamente: así como ellos se opusieron a Moisés con un poder falsificado, los falsos maestros se oponen al evangelio con una fe espuria. Los nombres aparecen en textos mágicos judíos y paganos, lo que confirma su difusión en el mundo antiguo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2390', 'spa', 'Sanar, curar — restaurar la salud de una enfermedad o dolencia, usado de los actos de sanidad divina y apostólica.', 'Sanar, curar — restaurar la salud de una enfermedad o dolencia, usado de los actos de sanidad divina y apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2391', 'spa', 'Jared, patriarca antediluviano en la genealogía de Jesús (hijo de Mahalalel, padre de Enoc)', 'Jared aparece en la genealogía de Lucas (3:37) como antepasado de Jesús del período antediluviano. Génesis 5:15-20 registra que Jared vivió 962 años y fue padre de Enoc (quien caminó con Dios y fue arrebatado). El nombre deriva del hebreo יֶרֶד (Yered), que posiblemente significa «descenso». Al incluir a estos antiguos patriarcas, Lucas traza el linaje de Jesús hasta Adán, subrayando su vínculo con toda la humanidad. La LXX traduce el nombre como Ἰάρεδ, aunque la tradición manuscrita de Lucas presenta ligeras variantes (Ἰάρετ, Ἰάρεθ). Las traducciones hispanas mantienen la forma «Jared» siguiendo la tradición desde Génesis.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2392', 'spa', 'Sanidad, curación; el acto o proceso de ser sanado', 'Este sustantivo designa el acto de curación o sanidad. En Lucas 13:32, Jesús dice «echo fuera demonios y realizo curaciones». En Hechos 4:22 se describe al hombre cojo sanado como evidencia del poder divino: tenía más de cuarenta años. En Hechos 4:30, los discípulos oran pidiendo que Dios extienda su mano para sanar. Los usos neotestamentarios abarcan el ministerio sanador de Jesús, la sanidad apostólica como señal confirmadora y la curación como actividad divina continua a través de la iglesia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2393', 'spa', 'Jaspe; piedra preciosa o semipreciosa usada en Apocalipsis para simbolizar el resplandor divino y el esplendor celestial', 'Gema opaca conocida en la antigüedad en diversos colores, el jaspe aparece exclusivamente en las visiones de gloria celestial del Apocalipsis. El que está sentado en el trono irradia luz ''semejante a jaspe y cornalina'' (Ap 4:3), y el resplandor de la Nueva Jerusalén se compara con jaspe, ''diáfano como el cristal'' (Ap 21:11). El muro de la ciudad está construido de jaspe (Ap 21:18) y el jaspe encabeza la lista de las piedras de los cimientos (Ap 21:19). El término proviene del hebreo yashpheh y se translitea de forma uniforme en las lenguas modernas: en español ''jaspe.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2394', 'spa', 'Jasón; creyente de Tesalónica que hospedó a Pablo y sus compañeros, posiblemente pariente de Pablo en Rom 16:21.', 'Jasón es un nombre griego que designa a un creyente de Tesalónica que brindó hospitalidad a Pablo y Silas durante su visita misionera. Cuando una turba atacó su casa, Jasón fue arrastrado ante las autoridades de la ciudad y acusado de dar cobijo a hombres que «actúan contra los decretos de César» (Acts 17:5-9). Tras pagar fianza, fue puesto en libertad. Un Jasón también aparece entre los saludos de Pablo en Rom 16:21 como «pariente», posiblemente la misma persona. El nombre, conocido por el héroe de la mitología griega, era adoptado frecuentemente por judíos helenizados como equivalente de Josué o Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2395', 'spa', 'Médico, doctor; sanador del cuerpo, usado en sentido literal y en los dichos proverbiales de Jesús sobre la sanidad espiritual.', 'Ἰατρός es la palabra griega estándar para un profesional de la medicina, derivada del verbo ἰάομαι (''sanar''). En el NT aparece tanto en sentido literal —Lucas es llamado ''el médico amado'' (Col 4:14), y la mujer con hemorragia gastó todo en médicos (Mc 5:26; Lc 8:43)— como en sentido proverbial en los dos dichos de Jesús: ''Los sanos no tienen necesidad de médico'' (Mt 9:12; Mc 2:17; Lc 5:31) y ''Médico, cúrate a ti mismo'' (Lc 4:23). El término abarca tanto al sanador profesional como la metáfora de la sanación espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2396', 'spa', 'he aquí, mira, ve (imperativo aoristo singular); orden de dirigir la atención hacia algo', 'Imperativo aoristo que significa «¡mira!» o «¡he aquí!»: una orden directa de prestar atención. Derivado del verbo εἶδον («vi»), esta forma aparece con frecuencia tanto en el griego clásico como en el bíblico. En el dialecto ático se escribe ἰδέ y se emplea como adverbio. Los poetas trágicos lo usan en pasajes líricos para dirigir la mirada del público. La fuerza imperativa convierte el acto de ver en una acción que se debe realizar. No se trata de observación pasiva, sino de atención activa y ordenada: ¡Mira! ¡Fíjate! ¡Contempla lo que tienes delante!');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2397', 'spa', 'forma, apariencia o aspecto exterior visible; el aspecto o la imagen que algo presenta a la vista', 'El sustantivo ἰδέα designa la forma exterior, la apariencia o el aspecto visible de algo, es decir, lo que se percibe a simple vista. Aunque la filosofía clásica empleó este término para referirse a las «formas» o «ideas» abstractas, en su uso más concreto simplemente significaba aspecto físico o tipo. Mateo 28:3 lo utiliza para describir al ángel junto al sepulcro: «Su apariencia era como un relámpago». La palabra enfoca el aspecto visible, lo que los testigos realmente vieron. En el uso bíblico no interviene el sentido filosófico platónico, sino la apariencia concreta y fenomenológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2398', 'spa', 'Propio, personal, privado; usado adverbialmente como ''en privado/aparte'' y sustantivado como ''los suyos''', 'ἴδιος es el adjetivo griego para la posesión personal y la pertenencia privada, opuesto a κοινός («común, compartido»). En los Evangelios marca con mayor frecuencia algo como distintivamente propio de alguien — su propia ciudad (Mt 9:1), sus propios bienes (Mt 25:14). La conocida expresión κατ᾽ ἰδίαν («en privado») aparece diecisiete veces, generalmente cuando Jesús se retira con los discípulos apartándose de las multitudes (Mt 14:13; 17:1). El Evangelio de Juan desarrolla un uso sustantivado de gran fuerza emotiva: «A lo suyo vino, y los suyos no le recibieron» (Jn 1:11). El español «propio» cubre con precisión el núcleo posesivo del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2399', 'spa', 'Persona sin formación, lego; quien carece de destreza profesional o educación formal en una materia.', 'Este sustantivo significaba originalmente «ciudadano particular» en contraposición a quien ocupaba un cargo público, pero en el Nuevo Testamento designa a una persona que carece de formación especializada o elocuencia. El Sanedrín reconoció que Pedro y Juan eran «hombres sin letras e indoctos» (Acts 4:13). Pablo lo emplea para referirse a personas ajenas o no instruidas que no pueden seguir el hablar en lenguas durante el culto (1 Cor 14:16, 23-24), y concede ser «inexperto en la palabra» mientras insiste en su conocimiento (2 Cor 11:6). El término connota falta de pericia formal, no necedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2400', 'spa', 'he aquí, mira (interjección); partícula que dirige la atención hacia lo que sigue', 'Partícula exclamativa que significa «¡he aquí!» o «¡mira!», aunque los gramáticos debaten si es verdaderamente un imperativo o un adverbio. Aparece con sustantivos («he aquí, una virgen»), pronombres («he aquí, yo estoy a la puerta») y verbos en cualquier tiempo («he aquí, él viene»). El Nuevo Testamento la emplea abundantemente, sobre todo en la narrativa y la literatura apocalíptica. Los ángeles anuncian con ἰδού, Jesús enseña con ella y Apocalipsis puntúa sus visiones con esta partícula. Funcionalmente, enmarca lo que sigue como algo significativo, sorprendente o digno de atención.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2401', 'spa', 'Idumea, la región al sur de Judea (nombre griego de Edom)', 'Idumea es el nombre griego de la región de Edom, situada al sur de Judea, derivado del hebreo אֱדֹם (Edom). Tras el exilio babilónico, los edomitas se desplazaron hacia el sur de Judea y la zona pasó a conocerse como Idumea. En tiempos del Nuevo Testamento era un territorio diferenciado, a veces bajo control judío; la familia herodiana tenía raíces idumeas. Marcos 3:8 menciona que personas venían de Idumea para escuchar a Jesús. La LXX normalmente transliteraba el hebreo como Ἐδώμ, mientras que las fuentes helenísticas preferían Ἰδουμαία.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2402', 'spa', 'sudor, transpiración; humedad que el cuerpo exuda por esfuerzo físico o calor', 'El sustantivo ἱδρώς significa sudor o transpiración, el fluido corporal que se exuda durante el esfuerzo físico, el calor o la angustia intensa. La literatura clásica asocia frecuentemente el sudor con el trabajo arduo, como en la máxima de Hesíodo de que los dioses pusieron el sudor antes de la virtud. Lucas 22:44 describe cómo el sudor de Jesús en Getsemaní se volvió «como grandes gotas de sangre que caían a tierra», una imagen que subraya la realidad física de su agonía. El término transmite la intensidad de la tensión y el sufrimiento extremo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2403', 'spa', 'Jezabel, la infame reina de Israel; usada simbólicamente en Apocalipsis para una falsa profetisa', 'Jezabel fue la esposa fenicia del rey Acab que promovió el culto a Baal en Israel y se opuso violentamente a los profetas de Dios (1 Reyes 16-21). Su nombre se convirtió en sinónimo de idolatría, inmoralidad sexual y persecución de los fieles. Apocalipsis 2:20 emplea su nombre de forma simbólica para referirse a una mujer o movimiento en Tiatira que se autodenomina profetisa pero enseña a los cristianos a practicar la inmoralidad sexual y a comer alimentos sacrificados a ídolos. Ya sea una persona real o una designación simbólica, el nombre evoca la seducción espiritual y la corrupción de la Jezabel veterotestamentaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2404', 'spa', 'Hierápolis (Ciudad Santa); ciudad del valle del Lico en Asia Menor', 'Ciudad de la provincia romana de Asia, situada en el valle del Lico cerca de Colosas y Laodicea. Su nombre significa «Ciudad Santa», probablemente en referencia a su célebre santuario pagano y sus fuentes termales, que la convertían en centro de peregrinación. Pablo la menciona en Colosenses 4:13 como lugar donde Epafras se esforzaba por los creyentes. La tradición cristiana primitiva asocia al apóstol Felipe con Hierápolis. Las tres ciudades —Colosas, Laodicea y Hierápolis— formaban un triángulo de comunidades abordadas directa o indirectamente en la correspondencia paulina, cada una con desafíos y oportunidades propias para el evangelio en una región helenizada y religiosamente diversa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2407', 'spa', 'ejercer el sacerdocio, desempeñar funciones sacerdotales, oficiar como sacerdote', 'Este verbo significa ejercer como sacerdote, realizando los deberes rituales y sacrificiales propios del sacerdocio. En el contexto judío, esto incluía ofrecer sacrificios, quemar incienso, bendecir al pueblo y mantener el culto del templo. Lucas 1:8 lo emplea para describir a Zacarías cumpliendo su servicio sacerdotal cuando recibió la visión del ángel Gabriel. El participio ἱερατεύειν indica la participación activa en el ministerio sacerdotal durante la semana de servicio de su división. El griego clásico también lo usaba para referirse al servicio sacerdotal de diversas divinidades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2408', 'spa', 'Jeremías, el profeta mayor; también citado en una atribución textual debatida', 'El profeta Jeremías aparece tres veces en el Evangelio de Mateo. En Mateo 2:17 introduce una cita de cumplimiento: «entonces se cumplió lo dicho por el profeta Jeremías». En Mateo 16:14 se recoge la especulación de que Jesús pudiera ser «Jeremías o alguno de los profetas». En Mateo 27:9 se atribuye una profecía a Jeremías, aunque el paralelo más cercano es Zacarías 11:13, un enigma textual que ha generado amplio debate. El nombre hebreo יִרְמְיָהוּ significa «Yahvé exalta» o «Yahvé establece». Los temas de juicio, sufrimiento y nuevo pacto en Jeremías lo convirtieron en punto natural de comparación con el ministerio de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2409', 'spa', 'sacerdote — quien realiza ritos sagrados y ofrece sacrificios, especialmente sacerdotes del templo judío y Cristo como sumo sacerdote', 'sacerdote — quien realiza ritos sagrados y ofrece sacrificios, especialmente sacerdotes del templo judío y Cristo como sumo sacerdote');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2410', 'spa', 'Jericó; la antigua ciudad fortificada cerca del río Jordán, prominente en la conquista del AT y en los relatos evangélicos del NT.', 'Ἰεριχώ es la forma griega indeclinable del hebreo Yerijó, la antigua ciudad en el bajo valle del Jordán. En el AT es la primera ciudad conquistada tras el Éxodo (Jos 6), y Hebreos 11:30 recuerda cómo sus muros cayeron por la fe. En los Evangelios, Jericó se encuentra en el último tramo del camino de Jesús hacia Jerusalén: allí sana al ciego Bartimeo (Mt 20:29; Mc 10:46; Lc 18:35), se encuentra con Zaqueo (Lc 19:1) y sitúa la parábola del buen samaritano en el peligroso camino de Jericó (Lc 10:30).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2411', 'spa', 'Templo — el recinto sagrado de Jerusalén, especialmente el complejo del templo con sus atrios, pórticos y santuario', 'ἱερόν se refiere al complejo entero del templo de Jerusalén —sus atrios, columnatas y recintos sagrados—, a diferencia de ναός, que designa únicamente el santuario interior. Cuando Jesús expulsa a los cambistas, entra en el ἱερόν (Mt 21:12; Mc 11:15), la amplia zona pública donde se realizaba el comercio y la enseñanza. Es en el ἱερόν donde Jesús enseña diariamente (Lc 19:47; 21:37), donde la iglesia primitiva se reúne tras Pentecostés (Hch 2:46; 5:20-21), y donde Pablo es apresado por la turba (Hch 21:27-30). El diablo sitúa a Jesús en el pináculo del ἱερόν durante la tentación (Mt 4:5; Lc 4:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2412', 'spa', 'propio de la santidad, reverente, digno de personas o asuntos sagrados; sacerdotal, decoroso', 'El adjetivo ἱεροπρεπής (literalmente "lo que conviene a lo sagrado") describe un comportamiento, porte o carácter apropiado para personas, lugares o asuntos santos. Transmite dignidad, reverencia y la gravedad propia de quienes participan en el servicio sagrado. En Titus 2:3 se instruye a las mujeres mayores a ser "reverentes en su conducta" — ἱεροπρεπεῖς en su porte, como corresponde a quienes enseñan y modelan la piedad. La palabra no significa meramente religioso, sino que implica la seriedad y dignidad propias de una vocación sagrada. Las fuentes clásicas la emplean para la conducta apropiada de sacerdotes o ceremonias sagradas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2413', 'spa', 'Sagrado, santo; lo que pertenece a la esfera divina, al servicio del templo o a lo consagrado para Dios.', 'Este adjetivo señala aquello que pertenece al ámbito divino: consagrado, apartado, impregnado de significación sagrada. Pablo emplea el neutro plural (τὰ ἱερά, ''las cosas sagradas'') al argumentar que quienes sirven en el altar del templo comen de las ofrendas (1 Co 9:13). A Timoteo se le recuerdan las ''sagradas escrituras'' (ἱερὰ γράμματα) que conoció desde la infancia (2 Ti 3:15). El final largo de Marcos habla de la ''sagrada e imperecedera proclamación'' de la salvación eterna (Mr 16:20). El término distingue la cualidad de lo consagrado y apartado para Dios de la simple bondad moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2414', 'spa', 'Ἱεροσόλυμα — Jerusalén; la ciudad santa, capital de Judea, en su forma griega helenizada', 'Ἱεροσόλυμα es la forma helenizada del hebreo Yerushalayim (Jerusalén), tratada como un neutro plural en griego. El Nuevo Testamento emplea dos formas: la indeclinable Ἰερουσαλήμ (más cercana al hebreo, preferida por Pablo, Hebreos y Apocalipsis) y la declinable Ἱεροσόλυμα (preferida por Mateo, Marcos y Juan). Esta última porta un registro más grecorromano, quizás reflejando la ciudad tal como la percibían los de fuera. Con 64 apariciones solo en esta forma, nombra el epicentro del drama bíblico: sede del culto del Templo, escenario de la pasión de Jesús y objeto de la esperanza escatológica. La Jerusalén celestial (Gá 4:26; Heb 12:22; Ap 21:2) transforma el topónimo en símbolo teológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2416', 'spa', 'robar templos, cometer sacrilegio al saquear recintos sagrados', 'Este verbo significa robar o saquear templos, sustrayendo objetos sagrados o tesoros del templo — un delito grave en la antigüedad considerado no solo hurto sino sacrilegio. Las fuentes clásicas describen el robo de templos como un acto criminal e impío que violaba la santidad de la propiedad divina. En Romans 2:22 Pablo lo emplea en su acusación contra los judíos hipócritas: "Tú que abominas los ídolos, ¿cometes sacrilegio?" La acusación puede referirse a lucrar con bienes de templos paganos o a violar la santidad del templo de Jerusalén por codicia. El verbo combina la fuerza del robo con la del sacrilegio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2417', 'spa', 'saqueador de templos, persona sacrílega; quien roba lugares o bienes sagrados', 'El sustantivo ἱερόσυλος designa a quien roba templos o comete sacrilegio — un saqueador de lugares sagrados. Las sociedades antiguas trataban a tales personas como criminales y como ofensores impíos contra los dioses. La palabra combina ἱερός (sagrado) con συλάω (robar, saquear). En Acts 19:37 el secretario de la ciudad de Éfeso defiende a Pablo y sus compañeros: no son "ni sacrílegos ni blasfemos de nuestra diosa." Esto los absolvía del cargo de atacar directamente el culto de Artemisa o de robar bienes del templo, aunque su predicación socavaba su adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2418', 'spa', 'servir como sacerdote, ministrar de manera sacerdotal, realizar servicio sagrado', 'El verbo ἱερουργέω significa realizar servicio sacerdotal o ministrar de manera sagrada y cultual. Combina ἱερός (sagrado) con ἔργον (obra), denotando servicio sagrado o ministerio ritual. En Romans 15:16 Pablo lo usa metafóricamente: describe su labor apostólica como "ministrar el evangelio de Dios" de manera sacerdotal, para que la ofrenda de los gentiles sea aceptable. El verbo eleva la evangelización al lenguaje cúltico — Pablo sirve como sacerdote cuyo sacrificio son los gentiles convertidos. Las fuentes clásicas lo emplean para la realización de ritos sagrados u ofrendas de sacrificios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2419', 'spa', 'Jerusalén — la ciudad santa, capital de Judea y sede del Templo; también usada simbólicamente para la ciudad celestial', 'Ἰερουσαλήμ es la forma semítica indeclinable del nombre de la ciudad, que conserva el hebreo Yerushalayim con mayor fidelidad que la helenizada Ἱεροσόλυμα. Lucas y Pablo prefieren marcadamente esta forma, mientras que Marcos y Juan tienden a la variante helenizada. Más allá de su referencia geográfica literal —la ciudad de David, sede del Templo y centro de peregrinación—, el nombre adquiere peso simbólico en el contraste paulino entre ''la Jerusalén actual'' y ''la Jerusalén de arriba'' (Gá 4:25-26), y en la visión de Hebreos de la ''Jerusalén celestial'' (Heb 12:22).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2420', 'spa', 'Sacerdocio, oficio sacerdotal; la función o dignidad del sacerdote', 'Este sustantivo designa el sacerdocio u oficio sacerdotal. Sus tres apariciones se encuentran en Hebreos 7, dentro del argumento sobre la superioridad del sacerdocio de Cristo según el orden de Melquisedec. Hebreos 7:11 pregunta si la perfección podía alcanzarse mediante el sacerdocio levítico. Hebreos 7:12 señala que al cambiar el sacerdocio, necesariamente cambia también la ley. Hebreos 7:24 declara que el sacerdocio de Jesús es permanente porque él vive para siempre. El uso neotestamentario es exclusivamente cristológico, contrastando el sacerdocio levítico temporal y hereditario con el sacerdocio eterno y superior de Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2421', 'spa', 'Isaí; padre del rey David, de Belén, antepasado de Jesús en la línea mesiánica.', 'Isaí (en hebreo Yishai) fue el padre betlemita del rey David y, por tanto, una figura clave en la genealogía mesiánica. Aparece en las genealogías de Jesús tanto en Mateo como en Lucas (Matt 1:5-6; Luke 3:32). Pablo cita Isaiah 11:10 en Rom 15:12 —«la raíz de Isaí se levantará para gobernar a las naciones»— aplicándolo a Cristo. En Acts 13:22, el sermón de Pablo en la sinagoga recuerda cómo Dios levantó a David, «hijo de Isaí», como rey. Las distintas tradiciones de transliteración reflejan el mismo nombre hebreo original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2422', 'spa', 'Jefté, el juez galaadita que libró a Israel de los amonitas', 'Jefté fue un juez de Israel cuya historia aparece en Judges 11-12. Nacido de una prostituta, fue expulsado por su familia pero luego llamado de vuelta para liderar a Israel contra Amón. Hizo un trágico voto de sacrificar lo primero que saliera de su casa al regresar victorioso, lo cual resultó en el sacrificio de su hija. A pesar de ello, es recordado como un libertador que Dios usó. Hebrews 11:32 lo incluye entre los héroes de la fe que "por fe conquistaron reinos, hicieron justicia y alcanzaron promesas." La referencia se centra en su liberación militar, no en su voto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2424', 'spa', 'Jesús; la forma griega del hebreo Yeshua/Josué, que significa ''YHWH salva'' — el nombre personal del Mesías y de otras figuras bíblicas', 'Jesús, la forma griega del nombre hebreo Yeshua o Josué, que significa ''YHWH salva''. Se refiere principalmente al Mesías, Jesucristo, pero también a otras personas que llevaban este nombre en tiempos bíblicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2425', 'spa', 'Suficiente, considerable, competente o numeroso; adjetivo que abarca adecuación de personas, magnitud, gran cantidad y (sustantivado) una fianza legal', 'Suficiente, considerable, competente o numeroso; adjetivo que abarca adecuación de personas, magnitud, gran cantidad y (sustantivado) una fianza legal');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2426', 'spa', 'suficiencia, competencia, aptitud; capacidad o cualificación adecuada para una tarea', 'El sustantivo ἱκανότης designa suficiencia, competencia o aptitud para un propósito: tener la capacidad o cualificación adecuada. Puede referirse tanto a una cantidad suficiente como a una capacidad o cualidad suficiente. En 2 Corintios 3:5, Pablo niega que los apóstoles posean competencia «de sí mismos», afirmando en cambio que «nuestra suficiencia proviene de Dios». La palabra subraya la aptitud o cualificación para el ministerio apostólico del nuevo pacto. Las fuentes clásicas la emplean para denotar idoneidad o capacidad en diversos contextos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2428', 'spa', 'súplica, ruego ferviente; rama portada por suplicantes; petición ardiente', 'El sustantivo ἱκετηρία designaba originalmente la rama de olivo o guirnalda que los suplicantes griegos portaban como símbolo de su petición, pero pasó a significar la súplica misma: oración ferviente o ruego. Las fuentes clásicas describen a los suplicantes sosteniendo estas ramas al acercarse a dioses o autoridades. Hebreos 5:7 lo emplea para las oraciones de Jesús durante los días de su vida terrenal, cuando «con gran clamor y lágrimas ofreció oraciones y súplicas» a Dios. El plural enfatiza la intensidad y fervor de sus peticiones, probablemente aludiendo a Getsemaní.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2429', 'spa', 'humedad, jugo; contenido líquido o hidratación en el suelo o la materia orgánica', 'El sustantivo ἰκμάς denota humedad o jugo: el líquido presente en el suelo, las plantas o los cuerpos. Los autores clásicos lo empleaban para fluidos corporales (sudor, sangre), savia vegetal y humedad del suelo. Lucas 8:6 lo usa en la parábola del sembrador: la semilla que cayó sobre la roca «se secó porque no tenía humedad» (ἰκμάδα). La falta de humedad en el suelo pedregoso impidió que la planta sobreviviera. La palabra destaca el contenido líquido esencial para la vida y el crecimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2430', 'spa', 'Iconio; antigua ciudad de la provincia de Galacia, parada importante en los viajes misioneros de Pablo.', 'Nombre de una importante ciudad de la provincia romana de Galacia (actual Konya, Turquía), mencionada en Hechos como lugar clave en el primer viaje misionero de Pablo. Pablo y Bernabé llegaron allí tras ser expulsados de Antioquía de Pisidia (Hch 13:51), predicaron con gran efecto en la sinagoga (Hch 14:1), pero finalmente huyeron de la persecución hacia Listra y Derbe (Hch 14:19, 21). La buena reputación de Timoteo en esa región se destaca en Hch 16:2, y Pablo recuerda sus padecimientos en Iconio en 2 Ti 3:11.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2431', 'spa', 'alegre, gozoso, jovial; que tiene disposición animada y generosa', 'El adjetivo ἱλαρός describe a alguien alegre, gozoso o de disposición animada: de espíritu luminoso, no sombrío ni reticente. Las fuentes clásicas lo emplean para una luz alegre, un trato amable o buenas noticias. Pablo cita un principio en 2 Corintios 9:7: «Dios ama al dador alegre» (ἱλαρὸν δότην). La palabra no solo enfatiza el acto de dar, sino el espíritu con que se da: generosidad gozosa y voluntaria, sin renuencia ni compulsión. La actitud importa tanto como la acción misma.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2432', 'spa', 'alegría, jovialidad, gozo; la cualidad de ser animado y generoso de espíritu', 'El sustantivo ἱλαρότης denota alegría, jovialidad o disposición gozosa: la cualidad de ser animado y generoso de corazón. Romanos 12:8 instruye que quien practica la misericordia lo haga «con alegría» (ἐν ἱλαρότητι). La palabra enfatiza que los actos de misericordia y compasión deben realizarse con gozo, no de mala gana ni con resentimiento. El espíritu con que se ejerce el ministerio importa profundamente. El uso clásico y septuagintal asocia ἱλαρότης con gozo y júbilo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2437', 'spa', 'Ilírico, provincia romana en la costa oriental del Adriático (Balcanes modernos)', 'Ilírico era una provincia romana situada a lo largo de la costa oriental del Adriático, abarcando partes de la actual Albania, Croacia, Bosnia y Montenegro. Romanos 15:19 lo menciona como el límite occidental de los viajes misioneros de Pablo: «desde Jerusalén y por los alrededores hasta el Ilírico, todo lo he llenado del evangelio de Cristo». Se debate si Pablo realmente entró en la provincia o solo llegó hasta sus fronteras, pero el nombre marca el alcance geográfico de su obra misionera, representando la frontera noroeste de su campo de trabajo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2438', 'spa', 'Correa o tira de cuero; usada para las cintas de las sandalias y las correas de atadura.', 'Palabra sencilla pero evocadora para designar una correa o tira de cuero. Aparece de forma memorable en la declaración de indignidad del Bautista: ''No soy digno de agacharme y desatar la correa de sus sandalias'' (Mr 1:7; Lc 3:16; Jn 1:27). La humilde correa de sandalia se convierte en poderoso símbolo de la distancia inconmensurable entre el precursor y el que viene. En Hch 22:25, la misma palabra designa las correas de cuero con que los soldados romanos ataron a Pablo para azotarlo. El término abarca todo objeto utilitario hecho de cuero en forma de tira.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2440', 'spa', 'Vestidura exterior o manto; en sentido amplio, ropa o vestidos en general, frecuentemente en plural', 'El griego ἱμάτιον designaba originalmente el manto rectangular exterior que se llevaba sobre la túnica (χιτών), pero el uso neotestamentario lo extiende a la ropa en general. Cuando una mujer toca el vestido de Jesús (Mt 9:20) o las multitudes tienden sus mantos en el camino (Mt 21:8), el plural ἱμάτια simplemente significa ''ropas''. Sin embargo, cuando Jesús instruye no volver por el ἱμάτιον (Mt 24:18) o los soldados se reparten su manto (Jn 19:23-24), se tiene a la vista el manto exterior específico. El español distingue bien entre ''vestiduras'' (sentido general) y ''manto'' (prenda exterior concreta).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2441', 'spa', 'Vestimenta, ropa; término colectivo para las prendas que se llevan puestas, especialmente en contextos de apariencia y riqueza.', 'Término general para la ropa o vestimenta; ἱματισμός se refiere al conjunto de prendas que una persona lleva, no a una sola pieza. En los Evangelios aparece en contrastes llamativos: la resplandeciente vestidura blanca de Jesús transfigurado (Lc 9:29), la espléndida ropa de los ricos (Lc 7:25) y los vestidos repartidos por los soldados en la crucifixión (Mt 27:35; Jn 19:24). Pablo lo emplea al declarar que no codició la plata, el oro ni la ropa de nadie (Hch 20:33). La evidencia multilingüe lo traduce consistentemente como sustantivo colectivo, subrayando su alcance como vestuario más que como prenda individual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2442', 'spa', 'anhelar, desear ardientemente, añorar con afecto; tener un anhelo entrañable', 'El verbo ἱμείρω (y su variante ὁμείρομαι) significa anhelar, añorar o desear intensamente, a menudo con un matiz de cariño profundo y apasionado. La poesía clásica lo emplea para expresar deseo, amor o anhelo intenso. En 1 Tesalonicenses 2:8 Pablo utiliza el participio para expresar su afecto profundo: «Tan grande es nuestro afecto por vosotros, que hubiéramos querido entregaros no solo el evangelio de Dios, sino también nuestras propias vidas». El verbo transmite un anhelo cálido y personal, un afecto pastoral que va más allá del mero deber.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2443', 'spa', 'Para que, a fin de que; que — conjunción de propósito-resultado que introduce cláusulas finales, sub-finales y de contenido', 'Una conjunción versátil que introduce cláusulas de propósito (''para que'', ''a fin de que'') y cláusulas de contenido (''que''). Expresa la intención, el objetivo o el contenido de una acción o declaración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2444', 'spa', 'para que, a fin de que, que (conjunción de propósito o resultado); donde (adverbio relativo)', 'Principalmente una conjunción que introduce cláusulas de propósito («para que»), resultado («de modo que») o contenido («que»). Originalmente un adverbio local que significaba «donde» en Homero, para la época del ático clásico se había gramaticalizado como el marcador dominante de finalidad. El Nuevo Testamento emplea ἵνα abrumadoramente para propósito y resultado: «Dios envió a su Hijo para que el mundo fuese salvo», «os escribo estas cosas para que sepáis». Se combina con el modo subjuntivo para expresar intención, plan divino y resultados deseados, lo que la convierte en una palabra teológicamente cargada en textos que describen los propósitos redentores de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2445', 'spa', 'El sustantivo propio Ἰόππη (Ioppe) designa a Jope, la antigua ciudad portuaria del Mediterráneo en la costa de Palestina (actual Jaffa/Yafo, hoy parte', 'El sustantivo propio Ἰόππη (Ioppe) designa a Jope, la antigua ciudad portuaria del Mediterráneo en la costa de Palestina (actual Jaffa/Yafo, hoy parte de Tel Aviv). Las diez apariciones en el NT se encuentran todas en Hechos 9-11, donde anclan dos relatos fundamentales: la resurrección de Tabita/Dorcas (Hch 9:36-43) y la conversión de Cornelio. Pedro reside en Jope en casa de Simón el curtidor y allí recibe su visión del lienzo con animales impuros (Hch 10:5-8, 32; 11:5, 13). Jope se convierte así en el eje geográfico donde el evangelio se abre por primera vez a los gentiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2446', 'spa', 'El Jordán; el río principal de Palestina, lugar del bautismo de Juan y de eventos bíblicos clave. Iordanēs es la forma griega del hebreo Yardēn, el rí', 'El Jordán; el río principal de Palestina, lugar del bautismo de Juan y de eventos bíblicos clave. Iordanēs es la forma griega del hebreo Yardēn, el río que fluye desde el Mar de Galilea hacia el sur hasta el Mar Muerto. En el NT, el Jordán es primordialmente el escenario del ministerio de Juan el Bautista: multitudes de Jerusalén y de toda Judea salían para ser bautizadas en sus aguas (Mt 3:5-6), y el propio Jesús vino desde Galilea para ser bautizado allí (Mt 3:13). El río también funciona como marcador de frontera geográfica: «al otro lado del Jordán» (Mt 4:15, 25; 19:1) designa la región de Transjordania. Sus ecos veterotestamentarios — el cruce de Israel bajo Josué, los milagros de Elías y Eliseo — le confieren una profunda resonancia simbólica como lugar de transición y encuentro divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2447', 'spa', 'Óxido, corrosión; veneno, ponzoña; sustancia destructiva o corruptora', 'Este sustantivo posee dos significados distintos pero relacionados: la herrumbre o corrosión de los metales y el veneno o ponzoña de serpientes. Romanos 3:13 cita el Salmo 140: «veneno de áspides hay debajo de sus labios», describiendo el habla humana como ponzoñosa. Santiago 3:8 llama a la lengua «llena de veneno mortal», extendiendo la metáfora. Santiago 5:3 habla literalmente del óxido: «vuestro oro y plata están corroídos, y su herrumbre testificará contra vosotros». Esta doble acepción —corrosión que destruye metales y veneno que mata— la hace idónea para describir cualquier cosa con poder destructivo y corruptor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2448', 'spa', 'Judá; nombre personal o tribal (forma genitiva) que refiere al patriarca, la tribu o el territorio de Judá', 'La forma genitiva de Ἰούδας (Judá), que aparece en contextos que invocan al patriarca y su legado tribal. La mayoría de las ocurrencias hacen referencia a la tribu o el territorio de Judá: la profecía de Miqueas citada en Mt 2:6 declara que Belén no es ''la menor entre los gobernantes de Judá''; Lucas 1:39 ubica el viaje de María ''a la región montañosa de Judá''; y Hebreos 7:14 y 8:8 conectan el sacerdocio de Cristo y el nuevo pacto con ''la tribu de Judá''. Una aparición en Lucas 3:26 nombra a un antepasado en la genealogía de Jesús como Ἰωδά, distinto del patriarca. El hebreo subyacente Yehudah (''alabanza'') ancla la resonancia teológica del nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2449', 'spa', 'Judea — la provincia meridional de Palestina centrada en Jerusalen, corazon de la nacion judia', 'Judea — la provincia meridional de Palestina centrada en Jerusalen, corazon de la nacion judia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2450', 'spa', 'judaizar, vivir como judíos, adoptar costumbres y prácticas judías', 'El verbo Ἰουδαΐζω significa adoptar costumbres judías, seguir la ley judía o vivir conforme a las prácticas judías, especialmente referido a gentiles que asumen la identidad judía o a judíos que insisten en la observancia judía. En Gálatas 2:14, Pablo confronta a Pedro: «Si tú, siendo judío, vives como los gentiles y no como judío, ¿cómo obligas a los gentiles a judaizar?». El verbo critica la exigencia de que los creyentes gentiles adopten las marcas identitarias judías como la circuncisión y las leyes alimentarias. Se traduce como «judaizar» o «vivir como judíos», refiriéndose a la imposición de requisitos de identidad judía sobre los cristianos gentiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2451', 'spa', 'judío, perteneciente a los judíos o al judaísmo; relativo a costumbres o identidad judías', 'El adjetivo Ἰουδαϊκός describe lo judío: lo perteneciente a las costumbres, prácticas o identidad judías. Puede modificar mitos, tradiciones, leyes o modos de vida. En Tito 1:14, Pablo advierte contra «mitos judíos» (Ἰουδαϊκοῖς μύθοις) y mandamientos de quienes rechazan la verdad. La expresión se refiere a falsas enseñanzas de influencia judía, posiblemente genealogías especulativas, tradiciones apócrifas o escrúpulos legalistas que distraían del evangelio. El adjetivo señala que estas enseñanzas están arraigadas en la tradición judía, no en la verdad apostólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2452', 'spa', 'judaicamente, a la manera judía, conforme a las costumbres judías', 'El adverbio Ἰουδαϊκῶς significa «a la manera judía» o «conforme a las costumbres judías», es decir, vivir según las prácticas y marcas identitarias judías. En Gálatas 2:14, Pablo contrasta vivir judaicamente con vivir como los gentiles: confronta a Pedro por vivir ἐθνικῶς (como gentil) y no Ἰουδαϊκῶς, y sin embargo obligar a los gentiles a judaizar. El adverbio describe un patrón de vida definido por las marcas identitarias judías: circuncisión, leyes dietéticas, observancia del sábado, entre otras. La cuestión de fondo es si estas prácticas son requisito para la identidad cristiana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2453', 'spa', 'Judío; Judea — adjetivo que denota identidad judía, usado sustantivado para designar a un judío o geográficamente para la región de Judea', 'En el Nuevo Testamento, Ἰουδαῖος identifica a alguien como perteneciente al pueblo judío — étnica, religiosamente o ambas cosas. Aparece casi 200 veces, especialmente en el Evangelio de Juan, donde a menudo designa a los dirigentes jerosolimitanos en contraste con Jesús y sus seguidores. El término conlleva un rico peso teológico: se trata del pueblo de la alianza de Dios, por medio del cual viene la salvación (Jn 4:22). En un caso (Jn 3:22), la forma femenina se refiere geográficamente a Judea, la tierra ancestral. Las traducciones distinguen sistemáticamente el uso personal («judío») del geográfico («Judea»), confirmando la diferencia semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2455', 'spa', 'Judas / Juda — nombre propio del hebreo yehudah, llevado por el patriarca, el traidor y varios otros', 'Judas / Juda — nombre propio del hebreo yehudah, llevado por el patriarca, el traidor y varios otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2456', 'spa', 'Julia, mujer cristiana en Roma a quien Pablo saluda', 'Julia se menciona en Romanos 16:15 entre los creyentes que Pablo saluda en Roma. Aparece junto a Filólogo (posiblemente su esposo o hermano), Nereo y su hermana, y Olimpas. El nombre era común en Roma, especialmente entre esclavos y libertas vinculadas a la casa imperial (gens Julia). Los saludos de Pablo revelan la red de comunidad cristiana en Roma antes de su llegada. No se conoce nada más sobre Julia aparte de esta referencia. Las traducciones transliteran el nombre como nombre propio sin adición interpretativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2458', 'spa', 'Junias (o Junia), pariente y colaborador de Pablo, destacado entre los apóstoles', 'Junias aparece en Romanos 16:7, donde Pablo saluda a Andrónico y Junias (o Junia) como sus parientes (συγγενεῖς, judíos compatriotas) y compañeros de prisión, quienes son «destacados entre los apóstoles». Si el nombre es masculino (Junias) o femenino (Junia) es objeto de debate, ya que la forma en acusativo Ἰουνιᾶν admite ambas lecturas. Muchos intérpretes antiguos lo entendieron como nombre femenino, pues Junia era un nombre romano común, mientras que Junias era extremadamente raro. Si es femenino, Junia sería una apóstol femenina, encarcelada por la fe y reconocida por el círculo apostólico. La frase «destacados entre los apóstoles» indica su notable reputación en la iglesia primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2459', 'spa', 'Justo, sobrenombre romano de tres personajes del Nuevo Testamento', 'Justo aparece como sobrenombre de tres hombres distintos en el Nuevo Testamento. Hechos 1:23 identifica a José, llamado Barsabás y apodado Justo, uno de los dos candidatos para reemplazar a Judas. Hechos 18:7 menciona a Ticio Justo, un temeroso de Dios en Corinto cuya casa Pablo usó tras dejar la sinagoga. Colosenses 4:11 envía saludos de Jesús, llamado Justo, colaborador de Pablo por el reino. El nombre latino significa «justo» o «recto», y pudo haber sido adoptado por conversos judíos o asignado como segundo nombre en contextos gentiles. Los tres hombres comparten solo el nombre, representando distintas facetas de la vida eclesial primitiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2461', 'spa', 'relativo a caballos o caballería; perteneciente a jinetes o tropas montadas', 'El adjetivo ἱππικός se refiere a caballos, jinetes o caballería, es decir, lo ecuestre o relativo a fuerzas montadas. Apocalipsis 9:16 lo emplea en la visión de Juan: «El número de las tropas montadas era doscientos millones» (τὸ ἀριθμὸν τοῦ στρατεύματος τοῦ ἱππικοῦ). La expresión describe una fuerza de caballería inmensa, parte de la imaginería apocalíptica del juicio. En el uso clásico, ἱππικός designa lo relativo a caballos, jinetes, entrenamiento ecuestre o unidades de caballería, en contraposición a la infantería. Las traducciones lo vierten consistentemente como «caballería».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2462', 'spa', 'Caballo; el equino domesticado, asociado especialmente con la guerra y la visión apocalíptica. ἵππος es la palabra griega estándar para caballo, y en ', 'Caballo; el equino domesticado, asociado especialmente con la guerra y la visión apocalíptica. ἵππος es la palabra griega estándar para caballo, y en el Nuevo Testamento aparece de manera predominante en las visiones apocalípticas del libro de Apocalipsis. Los cuatro jinetes cabalgan sobre caballos blanco, rojo, negro y pálido (Ap 6:2-8), y una caballería aterradora de doscientos millones aparece con caballos que tienen cabezas semejantes a leones y exhalan fuego y azufre (Ap 9:7-19). La única aparición fuera de Apocalipsis es Santiago 3:3, donde el freno del caballo ilustra cómo algo pequeño controla algo grande.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2464', 'spa', 'Isaac; el patriarca, hijo de Abraham y Sara, hijo de la promesa y antepasado de Israel. La forma griega indeclinable del hebreo Yitschaq (''él ríe''), q', 'Isaac; el patriarca, hijo de Abraham y Sara, hijo de la promesa y antepasado de Israel. La forma griega indeclinable del hebreo Yitschaq (''él ríe''), que nombra al hijo tan esperado nacido de Abraham y Sara. En el Nuevo Testamento, Isaac aparece en genealogías (Mt 1:2), en la enseñanza de Jesús sobre los patriarcas en el banquete escatológico (Mt 8:11) y en argumentos teológicos sobre la promesa divina frente al esfuerzo humano (Ro 9:10; Gá 4:28). Es la figura bisagra entre la fe de Abraham y las doce tribus de Jacob.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2465', 'spa', 'igual a los ángeles, semejante a los ángeles; que posee características o estatus angélico', 'El adjetivo ἰσάγγελος (literalmente «igual a los ángeles») describe a alguien que posee cualidades o estatus angélico. Lucas 20:36 lo emplea en la enseñanza de Jesús sobre la resurrección: quienes alcancen la resurrección «ya no pueden morir, porque son iguales a los ángeles y son hijos de Dios, siendo hijos de la resurrección». La comparación enfatiza la inmortalidad y la transformación: los creyentes resucitados serán como los ángeles en que no mueren ni se casan. La palabra no significa que los creyentes se conviertan en ángeles, sino que comparten ciertas características angélicas, en particular la inmortalidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2466', 'spa', 'Isacar, noveno hijo de Jacob y ancestro de una de las doce tribus de Israel', 'Isacar fue el noveno hijo de Jacob, nacido de Lea a través de su sierva. Su nombre, derivado del hebreo con el significado de «hay recompensa», se convirtió en la designación de una de las doce tribus de Israel. En Apocalipsis 7:7, representantes de la tribu de Isacar son contados entre los 144.000 siervos sellados, figurando como testimonio de la fidelidad de Dios a su pacto a través de todas las tribus. La lista apocalíptica sitúa a Isacar en quinto lugar, entre Gad y Zabulón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2467', 'spa', 'yo sé (perfecto de εἴδω con significado presente); haber visto y por tanto conocer', 'Tiempo perfecto de un verbo que significa «ver», pero que funciona con significado presente: «yo sé» (porque he visto). Es el verbo principal del griego para el conocimiento, no teórico sino experiencial, arraigado en la percepción. El paradigma completo incluye un aoristo εἶδον («vi»), usado como pasado de ὁράω, y este perfecto οἶδα («sé») con fuerza de presente. El patrón refleja raíces protoindoeuropeas compartidas con el latín video y el germánico wit. Los escritores bíblicos lo emplean para el conocimiento de Dios, la conciencia de hechos y el reconocimiento de la verdad. Jesús pregunta: «¿Sabéis lo que os he hecho?». El verbo presupone que el conocimiento proviene de la vista o de una revelación divina equivalente a ver.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2468', 'spa', 'Soy, eres, es (presente de indicativo de εἰμί en varias personas); afirmación simple de ser o existir', 'Formas del presente de indicativo del verbo «ser/estar» en sus diversas personas y variantes dialectales. Incluye las formas eólica ἔμμι, las variantes dóricas y épicas, las formas áticas estándar y las alternativas jónicas. Estas formas expresan existencia simple, predicación, identidad y ubicación, constituyendo la columna vertebral de la predicación griega. En los textos bíblicos adquieren un peso teológico especial en las declaraciones «Yo soy» de Jesús, la autorrevelación divina, las afirmaciones apostólicas y las declaraciones de identidad. Las variaciones dialectales reflejan la historia lingüística regional, pero la función semántica central permanece constante: afirmar lo que es, quién es alguien o dónde existe algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2469', 'spa', 'Iscariote — sobrenombre o epíteto de Judas (y en una ocasión de su padre Simón), probablemente derivado del hebreo אִישׁ קְרִיּוֹת (''hombre de Queriot', 'Iscariote — sobrenombre o epíteto de Judas (y en una ocasión de su padre Simón), probablemente derivado del hebreo אִישׁ קְרִיּוֹת (''hombre de Queriot''), lo que sugiere un origen en una localidad del sur de Judá. Ἰσκαριώθ (Iskariōth) es el sobrenombre indeclinable que acompaña a Judas, el discípulo que traicionó a Jesús. El nombre aparece en cada lista apostólica para distinguir a este Judas del otro apóstol del mismo nombre (Mt 10:4; Mc 3:19; Lc 6:16). Este epíteto acompaña a Judas a lo largo de su acuerdo para entregar a Jesús (Mt 26:14; Mc 14:10; Lc 22:3), y el Evangelio de Juan lo aplica de manera singular también al padre de Judas, Simón (Jn 6:71; 12:4; 13:2, 26). La variante Ἰσκαριώτης aparece en algunos manuscritos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2470', 'spa', 'Igual, mismo o equivalente en medida, cualidad o estatus; denota paridad o correspondencia.', 'Adjetivo que expresa igualdad o equivalencia, ἴσος aparece en contextos donde la paridad —ya sea justa o provocadora— está en juego. Los trabajadores de la parábola de la viña se quejan de que el amo ha hecho a los últimos ''iguales'' a quienes soportaron el calor del día (Mt 20:12), revelando el resentimiento humano ante la generosidad divina. Los falsos testigos contra Jesús no logran producir testimonios ''concordantes'' (Mr 14:56, 59). De manera más explosiva, se acusa a Jesús de ''hacerse igual a Dios'' (Jn 5:18), y Fil 2:6 habla de la igualdad con Dios como algo a lo que Cristo no se aferró. El español ''igual'' conserva tanto la dimensión matemática como la social del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2471', 'spa', 'Igualdad, equidad, justicia; proporción equitativa o trato justo', 'Este sustantivo denota igualdad, equidad o distribución justa. Pablo lo emplea tres veces al tratar la equidad económica en la iglesia. En 2 Corintios 8:13-14 expone el principio de igualdad en la ofrenda: «no para que otros tengan holgura y vosotros estrechez, sino por igualdad... para que vuestra abundancia supla la necesidad de ellos... a fin de que haya igualdad». Colosenses 4:1 ordena a los amos dar a los siervos «lo justo y equitativo», reconociendo obligaciones mutuas. El uso neotestamentario se centra en la distribución equitativa: equilibrio económico en el cuerpo de Cristo y trato justo en las jerarquías sociales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2472', 'spa', 'de igual valor, honor o privilegio; que comparte la misma posición o dignidad', 'Este adjetivo compuesto combina ''igual'' con ''honor'' o ''valor'', describiendo algo o alguien que comparte una posición equivalente. En 2 Pedro 1:1, los creyentes reciben una fe ''igualmente preciosa'' (ἰσότιμος) a la de los apóstoles, una afirmación asombrosa de que la misma calidad de confianza salvífica está disponible para todos los que creen, sin importar su cercanía a Jesús durante su ministerio terrenal. El término subraya la imparcialidad divina en la distribución del privilegio espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2473', 'spa', 'de igual ánimo, de la misma alma; que comparte el mismo espíritu, disposición o preocupación', 'Literalmente ''de alma igual'', este adjetivo describe una profundidad inusual de unidad en propósito y afecto. Pablo lo usa exclusivamente de Timoteo en Filipenses 2:20, diciendo que no tiene a nadie más ''de igual ánimo'' que se preocupe genuinamente por el bienestar de los filipenses. En contexto, Timoteo contrasta marcadamente con quienes ''buscan sus propios intereses, no los de Jesucristo''. La palabra no elogia un simple acuerdo intelectual, sino corazones verdaderamente alineados en compasión pastoral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2474', 'spa', 'Israel — el pueblo del pacto, la nación y la tierra; también el patriarca Jacob renombrado por Dios', 'El nombre propio indeclinable Israel (del hebreo Yisra''el) aparece 68 veces en el Nuevo Testamento y opera en varios niveles referenciales: el patriarca Jacob (raro en el NT), el pueblo del pacto (''los hijos de Israel'', Hch 5:21), la entidad nacional (''la casa de Israel'', Hch 7:42) y la tierra (''la tierra de Israel'', Mt 2:20-21). Pablo explota la significación estratificada del término, distinguiendo ''Israel según la carne'' (1 Co 10:18) del ''Israel de Dios'' (Gá 6:16). Todas las lenguas principales conservan el nombre de forma prácticamente idéntica, constancia interlingüística que refleja la continuidad teológica entre Antiguo y Nuevo Testamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2475', 'spa', 'Israelita — miembro del pueblo del pacto de Israel, usado como título de privilegio teocrático e identidad nacional.', 'Israelita no es meramente una etiqueta étnica, sino un título cargado de significado pactual. Cuando Pedro se dirige a las multitudes como ''¡Varones israelitas!'' (Hch 2:22, 3:12, 5:35) o Pablo se identifica como israelita (Ro 9:4, 11:1; 2 Co 11:22), la palabra evoca toda la herencia de elección divina, promesa y llamamiento. La observación de Jesús sobre Natanael —''¡He aquí un verdadero israelita en quien no hay engaño!'' (Jn 1:47)— juega con esta resonancia teológica, vinculando el nombre Israel con el patriarca que luchó con Dios. El término tiene mayor peso que ''hebreo'' (Hebraios) o ''judío'' (Ioudaios), invocando deliberadamente la relación sagrada del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2476', 'spa', 'Estar de pie, poner, colocar, hacer estar firme, detenerse o establecer; abarca postura física, colocación, perseverancia moral, cesación y confirmación', 'ἵστημι es el verbo maestro del Nuevo Testamento para la posición y la estabilidad, gobernando desde dónde se encuentra físicamente una persona hasta si un reino perdura. Su morfología cuenta la historia: el aoristo primero transitivo (ἔστησα) coloca y posiciona, mientras que el aoristo segundo intransitivo (ἔστη), el perfecto (ἕστηκα) y el presente medio permiten que personas y cosas simplemente estén de pie. El árabe escinde esto entre waqafa (estar de pie) e aqāma (erigir), exponiendo la división transitivo-intransitiva que el griego codifica mediante alternancia de tema. Desde el diablo colocando a Jesús en el pináculo del templo (Mt 4:5) hasta la declaración de Pablo de que el siervo de Dios «será sostenido firme» (Ro 14:4), ἵστημι ancla la teología neotestamentaria del posicionamiento divino y la perseverancia humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2477', 'spa', 'visitar con propósito de indagar; conocer personalmente, informarse sobre alguien', 'Este verbo significa más que una visita casual: implica ir con la intención de conocer, indagar u obtener información. En el griego clásico se usaba para examinar lugares, consultar oráculos o buscar información de personas. En Gálatas 1:18, Pablo dice que subió a Jerusalén ''para conocer'' (ἱστορῆσαι) a Cefas, permaneciendo quince días con él. El término sugiere que la visita de Pablo tenía un propósito investigativo específico: conocer al apóstol principal sin comprometer la independencia de su propia revelación del evangelio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2478', 'spa', 'Fuerte, poderoso, robusto; en comparativo, más fuerte o más poderoso; de fuerzas o condiciones, severo o intenso.', 'Fuerte, poderoso, robusto; en comparativo, más fuerte o más poderoso; de fuerzas o condiciones, severo o intenso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2479', 'spa', 'Fuerza, poder, potencia — capacidad inherente para la acción, ya sea física, espiritual o divina. El sustantivo ἰσχύς (ischus) designa la fuerza, el p', 'Fuerza, poder, potencia — capacidad inherente para la acción, ya sea física, espiritual o divina. El sustantivo ἰσχύς (ischus) designa la fuerza, el poder o la potencia inherentes: la capacidad de actuar con vigor. Aparece de manera central en el mandamiento derivado del Shemá de amar a Dios ''con todas tus fuerzas'' (Mc 12:30, 33; Lc 10:27), haciendo eco de Deuteronomio 6:5 LXX. Pablo lo invoca para referirse al ''poder de la fuerza'' de Dios (Ef 1:19; 6:10; 2 Ts 1:9), y las doxologías celestiales atribuyen ''poder'' al Cordero (Ap 5:12; 7:12). Pedro exhorta a servir ''con la fuerza que Dios provee'' (1 P 4:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2480', 'spa', 'Ser fuerte, tener poder o ser capaz; de cosas, tener fuerza o validez; prevalecer contra la oposición.', 'Ser fuerte, tener poder o ser capaz; de cosas, tener fuerza o validez; prevalecer contra la oposición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2481', 'spa', 'quizás, tal vez, posiblemente; expresa incertidumbre o suaviza una afirmación', 'Este adverbio introduce posibilidad sin compromiso, suavizando afirmaciones o expresando incertidumbre cortés. En Lucas 20:13, el dueño de la viña delibera: ''Quizás (ἴσως) respetarán a mi hijo''. La palabra expresa su esperanza incierta, creando una ironía conmovedora, ya que el lector sabe que los labradores matarán al hijo. El griego clásico usaba ἴσως para matizar afirmaciones (''aproximadamente'', ''probablemente'') o marcar vacilación retórica, haciendo las declaraciones menos absolutas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2482', 'spa', 'Italia; la península romana, sede de la capital imperial y punto de origen o destino de los viajes cristianos primitivos.', 'Nombre geográfico propio de la península itálica, sede de Roma y centro del poder imperial. En Hechos, Italia aparece como destino de viajes decisivos: Aquila y Priscila han llegado recientemente desde allí tras la expulsión de los judíos por decreto de Claudio (Hch 18:2), y el viaje de Pablo como prisionero hacia Italia impulsa la dramática narrativa de Hch 27:1-6. Hebreos se cierra con saludos de parte de ''los de Italia'' (Heb 13:24), un dato sugerente sobre el origen o los destinatarios de la carta. Las cuatro apariciones vinculan el movimiento de personas entre Italia y el Mediterráneo oriental.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2483', 'spa', 'itálico, perteneciente a Italia; específicamente la cohorte itálica', 'Este adjetivo designa algo como italiano en origen o asociación. En Hechos 10:1, Cornelio sirve como centurión de ''la cohorte itálica'' (σπεῖρα Ἰταλική), una unidad militar romana probablemente compuesta por voluntarios italianos destacados en Cesarea. Este detalle sitúa a Cornelio dentro de la infraestructura militar romana y al mismo tiempo resalta lo extraordinario de su piedad: un oficial gentil de una unidad explícitamente romana se convierte en el primer converso gentil pleno, derribando el muro entre judío y gentil por iniciativa del Espíritu.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2484', 'spa', 'Itureo, perteneciente a Iturea; región al noreste de Galilea en la cordillera del Antilíbano', 'Este adjetivo se refiere a Iturea, una tetrarquía ubicada al noreste de Galilea en la cordillera del Antilíbano. Lucas 3:1 menciona a Felipe como tetrarca «de la región de Iturea y Traconítide», proporcionando el contexto geográfico-político del ministerio de Juan el Bautista. Los itureos eran descendientes de Ismael (véase 1 Crónicas 5:19), y para el siglo I su territorio había sido incorporado al sistema administrativo herodiano. La precisión de Lucas ancla la historia sagrada en realidades políticas fechables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2486', 'spa', 'Pez; una criatura acuática, usado literalmente en narrativas de alimentación, pesca y comidas posteriores a la resurrección. Un sustantivo común para ', 'Pez; una criatura acuática, usado literalmente en narrativas de alimentación, pesca y comidas posteriores a la resurrección. Un sustantivo común para pez que aparece en algunas de las escenas más vívidas de los Evangelios: la alimentación de los cinco mil con cinco panes y dos peces (Mt 14:17-19), la moneda encontrada en la boca de un pez (Mt 17:27) y la pregunta de si un padre le daría una serpiente a su hijo en lugar de un pez (Mt 7:10). En cada caso, la palabra es completamente concreta y literal: no se desarrolla ninguna extensión metafórica o simbólica en el uso del NT.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2487', 'spa', 'Pisada, huella; rastro dejado al caminar; metafóricamente, el camino o ejemplo a seguir', 'Este sustantivo significa literalmente pisada o huella, pero desarrolla un rico uso metafórico para referirse a seguir el ejemplo o el camino de alguien. Romanos 4:12 habla de «los que siguen las pisadas de la fe de nuestro padre Abraham», imitando su ejemplo. En 2 Corintios 12:18 Pablo pregunta si él y Tito «no anduvieron con las mismas pisadas», es decir, con la misma conducta y espíritu. 1 Pedro 2:21 dice que Cristo padeció «dejándoos ejemplo, para que sigáis sus pisadas». El uso neotestamentario es enteramente metafórico: seguir el patrón o ejemplo dejado por los predecesores en la fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2490', 'spa', 'Joanán, un antepasado de Jesús en la genealogía de Lucas', 'Joanán aparece en Lucas 3:27 como uno de los nombres en la línea ancestral que va de Jesús hasta Adán. El nombre es una forma griega del hebreo Yojanán, que significa «Yahvé es misericordioso». La genealogía de Lucas difiere de la de Mateo al trazar el linaje por Natán en lugar de Salomón, e incluye muchos nombres conocidos únicamente por esta lista. Cada nombre, por más oscuro que sea para la historia, atestigua que el Mesías de Dios surgió de un linaje humano real que abarca generaciones de fidelidad al pacto y paciencia divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2491', 'spa', 'Juan — forma helenizada del hebreo Yojanán (''YHWH es misericordioso''), que designa a varias figuras clave del NT, incluidos el Bautista y el Apóstol', 'Ἰωάννης es la forma griega del hebreo Yojanán, que significa «YHWH es misericordioso». Sus 135 apariciones en el Nuevo Testamento se distribuyen entre varias figuras, pero dos predominan. Juan el Bautista, la voz que clama en el desierto (Mt 3:1-3), concentra la mayor parte — el precursor profético que bautizó a Jesús y fue decapitado por Herodes Antipas. Juan hijo de Zebedeo, uno de los Doce y miembro del círculo íntimo de Jesús junto con Pedro y Jacobo (Mt 4:21; Mr 5:37), es el segundo referente principal y se le asocia tradicionalmente con el cuarto Evangelio y las epístolas joánicas. Otros portadores incluyen a Juan Marcos, compañero de Pablo y Bernabé (Hch 12:12, 25), y al padre de Simón Pedro (Jn 1:42; 21:15-17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2492', 'spa', 'Job, el justo sufriente del libro veterotestamentario que lleva su nombre', 'Job es el protagonista de la meditación más extensa de las Escrituras sobre el sufrimiento inocente y la soberanía divina. Santiago 5:11 presenta la perseverancia de Job como ejemplo para los creyentes que sufren, señalando «el propósito del Señor» revelado en su historia: que Dios es compasivo y misericordioso. Aunque Job luchó con profundas preguntas sobre la justicia divina, perseveró en la fe a pesar de perder riqueza, hijos y salud. Su historia demuestra que la fidelidad no es transaccional y que los caminos de Dios trascienden la comprensión humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2493', 'spa', 'Joel, el profeta veterotestamentario cuya profecía cita Pedro en Pentecostés', 'Joel fue un profeta cuyos oráculos anunciaban tanto la devastación por plagas de langostas como la restauración venidera. Hechos 2:16 cita Joel 2:28-32 cuando Pedro explica el derramamiento de Pentecostés: «Esto es lo que fue dicho por el profeta Joel». La visión de Joel sobre el Espíritu derramado sobre toda carne —hijos e hijas profetizando, ancianos y jóvenes viendo visiones— encuentra su cumplimiento inicial en el aposento alto. La cita autoriza los fenómenos carismáticos como divinamente prometidos, no como algo aberrante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2494', 'spa', 'Jonám, un antepasado de Jesús en la genealogía de Lucas', 'Jonám es otro nombre en el registro genealógico de Lucas, que aparece en 3:30 entre Elmadám y José. Como muchos en la lista de Lucas, Jonám es por lo demás desconocido para la historia bíblica. El nombre puede ser una variante de Joanán o estar relacionado con Jonás. La genealogía de Lucas cumple un propósito teológico distinto al de Mateo: mientras Mateo traza la descendencia real por Salomón para establecer el derecho legal de Jesús al trono de David, Lucas avanza por Natán para enfatizar el linaje humano real de Jesús.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2495', 'spa', 'Jonás — el profeta del AT cuya señal (tres días en el gran pez) Jesús invoca como tipo de su propia muerte y resurrección.', 'Las nueve apariciones neotestamentarias de Ἰωνᾶς se refieren al profeta veterotestamentario Jonás, y todas aparecen en un único contexto teológico: la invocación de Jesús de ''la señal de Jonás'' como la única señal dada a una generación incrédula. Los tres días que Jonás pasó en el vientre del gran pez prefiguran los tres días del Hijo del Hombre en el corazón de la tierra (Mt 12:39-41; 16:4; Lc 11:29-30, 32). Jesús también señala el arrepentimiento de los ninivitas ante la predicación de Jonás como reproche: alguien mayor que Jonás está aquí, y sin embargo esta generación se niega a arrepentirse. El nombre hebreo (Yonah, que significa ''paloma'') añade una capa evocadora que los primeros cristianos no habrían pasado por alto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2497', 'spa', 'Jorim, antepasado de Jesús en la genealogía de Lucas', 'Jorim aparece en Lucas 3:29 como un eslabón en la cadena genealógica que conecta a Jesús con Adán. Este nombre no se encuentra en ningún otro pasaje de las Escrituras, y no sabemos nada de este individuo más allá de su lugar en la genealogía. Tales nombres llenan la lista de Lucas, recordando al lector que detrás de las figuras bíblicas célebres hubo innumerables creyentes anónimos cuya fidelidad importó. Las promesas de Dios avanzaron tanto a través de los célebres (David, Abraham) como de los desconocidos (Jorim, Resa, Joanán).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2499', 'spa', 'Josés (forma griega de José); nombre de varios personajes del Nuevo Testamento', 'Forma griega del nombre hebreo José, que aparece con diversas variantes ortográficas (Ἰωσῆς, Ἰωσή, Ἰωσήφ). La tradición textual muestra considerable variación en la escritura entre los manuscritos. El Nuevo Testamento menciona a varios hombres con este nombre: un hermano de Jesús nombrado en Marcos 6:3 y Mateo 13:55, un hijo de María presente en la crucifixión (Mateo 27:56, Marcos 15:40, 47), y otro nombre para Bernabé (Hechos 4:36). La ubicuidad de este nombre en el judaísmo del siglo primero refleja la importancia patriarcal y la popularidad de José. Las variantes ortográficas no indican personas distintas, sino preferencias dialectales y de los copistas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2500', 'spa', 'Josés, forma abreviada de José; nombre de dos personajes del Nuevo Testamento', 'Josés es una forma abreviada de José que aparece como nombre de dos hombres vinculados a Jesús. Marcos 6:3 enumera a Josés entre los hermanos de Jesús (Mateo 13:55 tiene «José» en algunos manuscritos). Marcos 15:40 y 15:47 mencionan a otro Josés, hijo de María (distinta de la madre de Jesús), cuyo hermano era Jacobo. Esta María estuvo al pie de la cruz y fue testigo de la sepultura de Jesús. Las variantes textuales entre «Josés» y «José» en ciertos manuscritos reflejan el uso intercambiable de la forma completa y la abreviada. Los dos Josés representan el círculo familiar de Jesús y la comunidad de mujeres discípulas fieles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2501', 'spa', 'Jose — nombre propio indeclinable llevado por varias figuras biblicas, desde el patriarca hasta el esposo de Maria', 'Jose — nombre propio indeclinable llevado por varias figuras biblicas, desde el patriarca hasta el esposo de Maria');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2503', 'spa', 'iota, la letra más pequeña del alfabeto griego; representa el detalle más mínimo', 'Iota (del hebreo yod) es la letra más pequeña del alfabeto griego, equivalente a la ''i'' en español. En Mateo 5:18, Jesús declara que «ni una iota ni una tilde pasará de la Ley hasta que todo se haya cumplido». Esta hipérbole subraya la autoridad perdurable de las Escrituras y su cumplimiento total en Cristo: hasta la marca ortográfica más diminuta tiene peso divino. Jesús no anula la Ley sino que la cumple hasta en su más mínimo detalle, validando cada trazo mientras transforma su función.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2504', 'spa', 'Y yo, a mí también — crasis ática de καί y ἐγώ que une al hablante con lo anterior o añade énfasis.', 'Forma contracta (crasis) del griego ático que fusiona καί (''y/también'') con ἐγώ (''yo''). Este pronombre compacto aparece en algunas de las declaraciones más célebres del Nuevo Testamento. Cuando καί funciona como conjunción simple, vincula al hablante con lo que precede: ''Y yo os daré descanso'' (Mt 11:28), ''Y yo te digo que tú eres Pedro'' (Mt 16:18). Cuando καί lleva fuerza adverbial (''también''), subraya la inclusión personal o la reciprocidad del hablante: ''Yo también le confesaré delante de mi Padre'' (Mt 10:32). El español distingue estos matices con claridad: ''y yo'' frente a ''también yo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2505', 'spa', 'así como, conforme a; introduce una comparación o conformidad', 'Este adverbio funciona como «así como» o «conforme a lo que», estableciendo una correspondencia entre dos realidades. En Mateo 27:10, introduce la cita de cumplimiento: «conforme a lo que (καθά) el Señor me indicó». La palabra señala que los acontecimientos en torno al dinero de la traición de Judas y al campo del alfarero se ajustan al patrón profético. Καθά marca la alineación entre la profecía veterotestamentaria (aquí un compuesto de Zacarías y Jeremías) y el cumplimiento evangélico, mostrando la soberanía divina orquestando incluso las consecuencias de la traición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2506', 'spa', 'demolición, destrucción, derribo; desmantelamiento de fortalezas o argumentos', 'Este sustantivo designa la acción de derribar, demoler o destruir, y aparece tres veces en 2 Corintios dentro de la discusión paulina sobre la autoridad apostólica. En 2 Corintios 10:4 Pablo describe armas espirituales «poderosas para la destrucción de fortalezas». En 10:8 y 13:10 defiende su autoridad, dada «para edificación y no para destrucción». El uso clásico incluye demolición de edificios, derrocamiento e incluso reducción médica de hinchazón. Pablo lo emplea metafóricamente tanto en sentido positivo (destruir argumentos falsos) como negativo (uso indebido de autoridad que derriba en vez de edificar).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2507', 'spa', 'Bajar (de una cruz o altura); derribar, demoler (estructuras); deponer, derrocar (del poder).', 'Verbo poderoso que significa arrancar o hacer descender algo o a alguien de una posición elevada, ya sea física, estructural o política. Sus usos neotestamentarios más conmovedores describen el descenso del cuerpo de Jesús de la cruz (Mr 15:36, 46; Lc 23:53; Hch 13:29), donde el español ''bajar/habiendo bajado'' enfatiza el movimiento descendente de una remoción reverente. El mismo verbo derriba graneros en la parábola del rico insensato (Lc 12:18) y destruye fortalezas intelectuales en la imaginería de guerra espiritual de Pablo (2 Co 10:5). En el Magnificat de María alcanza su cumbre teológica: Dios ''derribó de sus tronos a los poderosos'' (Lc 1:52), transmitiendo la fuerza de la inversión divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2508', 'spa', 'podar, limpiar, purificar; especialmente de vides, quitar el crecimiento improductivo', 'Este verbo significa limpiar eliminando lo improductivo o contaminante. Su uso agrícola principal consiste en podar vides, cortando las ramas muertas o excesivas para que la planta produzca mejor fruto. En Juan 15:2, Jesús emplea la imagen vitícola: «Todo pámpano que da fruto, lo poda (καθαίρει) para que dé más fruto». La metáfora describe el cuidado disciplinario de Dios: él quita lo que obstaculiza la fecundidad, no para destruir sino para potenciar una vida abundante. La poda implica una pérdida dolorosa al servicio de una ganancia mayor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2509', 'spa', 'Así como, de la misma manera que; conjunción comparativa que introduce un paralelo o analogía entre dos situaciones. Formada a partir de κατά («según»', 'Así como, de la misma manera que; conjunción comparativa que introduce un paralelo o analogía entre dos situaciones. Formada a partir de κατά («según») y el relativo ἅ («las cosas que»), introduce una analogía o paralelo, dirigiendo la atención del lector a una correspondencia entre dos realidades. Pablo emplea con frecuencia esta partícula en sus epístolas: «como también David declara la bienaventuranza del hombre...» (Ro 4:6), «así como tenemos muchos miembros en un solo cuerpo» (Ro 12:4), y «así como el cuerpo es uno y tiene muchos miembros» (1 Co 12:12). La evidencia multilingüe (español así como, francés comme/de même que, alemán gleichwie) la traduce consistentemente con frases comparativas, confirmando su función única como marcador de analogía a nivel discursivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2510', 'spa', 'sujetar, prender, aferrarse a; agarrarse con fuerza a algo', 'Este verbo significa sujetar o adherir algo a otra cosa, a menudo con sentido de aferrarse o asir. En Hechos 28:3, una víbora «se prendió» (καθῆψεν) de la mano de Pablo mientras este recogía leña para el fuego en Malta. La palabra transmite la repentina fijación o agarre de la serpiente sobre la mano de Pablo, lo que llevó a los isleños a esperar que se hinchara o cayera muerto. La inmunidad de Pablo ante la mordedura se convierte en señal que confirma su autoridad apostólica y la protección divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2511', 'spa', 'Limpiar o purificar; hacer limpio fisica (sanar leprosos, declarar alimentos puros) o espiritualmente (quitar el pecado y la impureza moral)', 'Limpiar o purificar; hacer limpio fisica (sanar leprosos, declarar alimentos puros) o espiritualmente (quitar el pecado y la impureza moral)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2512', 'spa', 'Purificación, limpieza; acto ritual o ceremonial de hacer limpio, especialmente en la práctica religiosa judía.', 'Καθαρισμός es la forma sustantiva de καθαρίζω (''limpiar'') y designa el proceso o rito de purificación. En los Evangelios aparece en contextos ceremoniales claramente judíos: las tinajas de piedra en Caná están destinadas ''a los ritos de purificación de los judíos'' (Jn 2:6), la disputa entre los discípulos de Juan y un judío versa sobre la purificación (Jn 3:25), y Jesús envía a los leprosos sanados a ofrecer lo que Moisés mandó ''para tu purificación'' (Mr 1:44; Lc 5:14). Lucas 2:22 se refiere a la purificación mosaica tras el parto. Hebreos 1:3 eleva el término a la ''purificación de los pecados'' realizada por Cristo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2513', 'spa', 'Limpio, puro — ritualmente inmaculado, moralmente intachable o físicamente impecable.', 'Limpio, puro — ritualmente inmaculado, moralmente intachable o físicamente impecable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2514', 'spa', 'pureza, limpieza; purificación moral o ceremonial', 'Este sustantivo designa el estado o cualidad de ser puro, ya sea en sentido de limpieza física, integridad moral o aptitud ceremonial. En Hebreos 9:13 se refiere a «la pureza (καθαρότητα) de la carne» alcanzada mediante los ritos del Antiguo Pacto: la aspersión de cenizas de una novilla roja y de sangre animal que santificaba a los ceremonialmente contaminados. El término subraya la limpieza externa y física que dichos ritos proporcionaban, en contraste con la purificación más profunda de la conciencia que la sangre de Cristo realiza. La pureza exterior señalaba la necesidad de una purificación interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2515', 'spa', 'asiento, silla; cátedra de enseñanza; posición que representa autoridad', 'Este sustantivo designa un asiento o silla, con referencia especial a posiciones de autoridad o enseñanza. En Mateo 21:12 y Marcos 11:15 se describe a Jesús volcando «los asientos de los que vendían palomas» durante la purificación del templo. Mateo 23:2 lo usa metafóricamente: «Los escribas y fariseos se sientan en la cátedra de Moisés», es decir, ocupan la posición de autoridad docente. El uso clásico abarca diversos tipos de asiento, la postura de sentarse y, de manera específica, la silla del maestro. En el Nuevo Testamento el término comprende tanto el mobiliario literal (bancos de los mercaderes del templo) como la posición simbólica de enseñanza autorizada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2516', 'spa', 'Sentarse, estar sentado, permanecer sentado; postura física de reposo o presencia sostenida en un lugar.', 'Καθέζομαι significa sentarse o permanecer sentado, describiendo una postura corporal deliberada. Aparece en contextos que van desde el niño Jesús sentado entre los maestros del templo (Lc 2:46) hasta Jesús sentado y cansado junto al pozo de Jacob (Jn 4:6), María sentada en casa durante su duelo (Jn 11:20) y los dos ángeles sentados en el sepulcro vacío (Jn 20:12). El verbo se solapa con κάθημαι, pero tiende a enfatizar la acción de tomar asiento o acomodarse en una posición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2517', 'spa', 'En orden, sucesivamente; que denota sucesión ordenada, ya sea en la disposición narrativa o en la progresión temporal.', 'Este adverbio significa «en orden» o «sucesivamente», indicando una disposición ordenada y consecutiva. Lucas lo emplea de manera programática en su prólogo, declarando su intención de escribir «por orden» (Luke 1:3), y nuevamente para describir a Jesús viajando «por ciudades y aldeas» de manera sucesiva (Luke 8:1). En Hechos, marca el relato ordenado de Pedro sobre los acontecimientos (Acts 11:4), los profetas hablando «sucesivamente» desde Samuel en adelante (Acts 3:24) y el recorrido sistemático de Pablo por Galacia y Frigia (Acts 18:23). Transmite la idea de disposición metódica y progresión secuencial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2518', 'spa', 'Dormir físicamente; en sentido figurado, estar espiritualmente aletargado, moralmente desatento o muerto.', 'Dormir físicamente; en sentido figurado, estar espiritualmente aletargado, moralmente desatento o muerto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2521', 'spa', 'Sentarse, estar sentado; sentarse en trono o reinar con autoridad; habitar, residir en un lugar o condición.', 'El verbo griego κάθημαι (''sentarse, estar sentado'') es una forma deponente en voz media cuyo campo semántico se extiende desde lo cotidiano hasta lo majestuoso. En su uso más frecuente describe el acto de sentarse con autoridad: Cristo entronizado a la diestra de Dios (Mt 19:28; 26:64), un rey en su trono o un juez que preside un tribunal. También cubre el sentarse físico ordinario: junto al mar (Mt 13:1), en la plaza (Mt 11:16) o en el puesto de tributos donde Jesús encontró a Mateo (Mt 9:9). Un tercer sentido, más figurado, emerge en pasajes como Mt 4:16 y Lc 1:79, donde quienes ''están sentados en tinieblas'' habitan en una condición estable de necesidad espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2522', 'spa', 'diario, de cada día; relativo a lo que ocurre cotidianamente', 'Este adjetivo describe algo que ocurre o pertenece a cada día, literalmente «conforme al día». En Hechos 6:1 modifica la «distribución diaria» (διακονία καθημερινή) de alimentos a las viudas en la iglesia de Jerusalén. El término destaca la regularidad y continuidad del ministerio asistencial de la iglesia primitiva: no se trataba de caridad ocasional, sino de provisión sistemática y cotidiana. La queja de que las viudas helenistas eran desatendidas en esta distribución condujo al nombramiento de los Siete, mostrando cómo las necesidades prácticas impulsaron soluciones organizativas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2523', 'spa', 'Sentarse, tomar asiento; causativamente, sentar a alguien; tambien permanecer, quedarse o establecerse en un lugar', 'Sentarse, tomar asiento; causativamente, sentar a alguien; tambien permanecer, quedarse o establecerse en un lugar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2524', 'spa', 'Bajar, descender, hacer descender; soltar algo hacia abajo mediante cuerda, sábana o abertura.', 'Describe el acto deliberado de hacer descender o bajar algo desde una posición elevada. En los Evangelios, unos amigos bajan a un paralítico a través de una abertura en el techo para acercarlo a Jesús (Lc 5:19), y en Hechos, Pablo es descolgado en un canasto por la muralla de la ciudad (Hch 9:25). En las visiones de Pedro, un gran lienzo es bajado del cielo (Hch 10:11; 11:5). El verbo implica siempre un movimiento descendente controlado, no una caída accidental, lo cual subraya la intencionalidad de cada escena narrativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2525', 'spa', 'Designar o constituir en un cargo; conducir o escoltar; quedar establecido en un lugar.', 'Designar o constituir en un cargo; conducir o escoltar; quedar establecido en un lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2526', 'spa', 'En la medida en que, según, en cuanto; adverbio de proporción o correspondencia.', 'Adverbio de conexión que establece un criterio de medida o proporción entre dos realidades. Pablo lo emplea para reconocer la limitación humana junto a la ayuda divina: ''no sabemos lo que debemos pedir'' (Ro 8:26). En 2 Corintios 8:12 aparece dos veces, enmarcando el principio de que la generosidad es aceptable según lo que uno tiene, no según lo que no tiene. En 1 Pedro 4:13 vincula el sufrimiento presente con la futura alegría en la revelación de la gloria de Cristo. El matiz proporcional es clave: no indica mera condición, sino correspondencia graduada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2527', 'spa', 'del todo, enteramente; en absoluto, de ninguna manera', 'Este adverbio significa «en general», «enteramente» o «en absoluto», según el contexto. En Hechos 4:18, el Sanedrín ordena a Pedro y Juan «no hablar ni enseñar en absoluto (καθόλου) en el nombre de Jesús». El término enfatiza la totalidad: una prohibición exhaustiva, no una restricción parcial. El concilio intentó imponer una interdicción absoluta sobre la proclamación cristiana, que los apóstoles rechazaron de inmediato: «No podemos dejar de hablar de lo que hemos visto y oído» (4:20). Καθόλου marca la colisión entre la autoridad religiosa y la comisión profética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2528', 'spa', 'armar completamente, equipar por entero; estar completamente armado o pertrechado', 'Este verbo significa equipar o armar completamente con armamento o armadura, frecuentemente en voz media con el sentido de armarse a sí mismo. En Lucas 11:21, Jesús describe a un «hombre fuerte, completamente armado (καθωπλισμένος), que guarda su propio palacio». El participio evoca un estado de plena disposición defensiva: armas desenvainadas, armadura colocada, vigilancia constante. El punto de la parábola llega en el versículo 22: cuando «uno más fuerte que él» lo ataca y lo vence, todo su armamento resulta insuficiente. Jesús es el más fuerte que saquea los bienes de Satanás, liberando a los cautivos a pesar de la armadura completa del adversario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2529', 'spa', 'percibir claramente, observar, ver con nitidez; discernir o comprender', 'Este verbo significa mirar desde arriba, observar con claridad o percibir con entendimiento. En Romanos 1:20, Pablo argumenta que los atributos invisibles de Dios «se perciben claramente (καθοράται) desde la creación del mundo, siendo entendidos a través de las cosas hechas». El verbo implica no una mirada casual, sino una observación atenta que conduce al conocimiento. La creación misma funciona como revelación: el mundo visible manifiesta al Dios invisible con suficiente claridad para que la humanidad quede «sin excusa» por suprimir este conocimiento. La teología natural posee fuerza evidencial porque Dios se ha hecho καθοράται a través de sus obras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2530', 'spa', 'Porque, por cuanto, según; conjunción causal o proporcional que vincula razón o manera con un resultado.', 'Conjunción derivada de la expresión ''καθ'' ὅ τι'' — literalmente ''según lo que'' — que introduce ya sea una razón o un criterio de proporción. En Lucas-Hechos funciona casi siempre como causal: ''porque también él es hijo de Abraham'' (Lc 19:9) o ''porque no era posible que la muerte lo retuviera'' (Hch 2:24). Pero en Hch 2:45 y 4:35 adquiere un sentido proporcional: se repartía ''según'' la necesidad de cada uno. El español capta bien esta dualidad: ''porque'' para lo causal y ''según'' para lo proporcional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2531', 'spa', 'Así como, tal como; cómo — conjunción comparativa que introduce correspondencia o modo, raramente usada como interrogativa', 'καθώς es la conjunción fundamental del Nuevo Testamento para establecer paralelos y patrones: «así como está escrito», «como el Padre me envió». Prácticamente todas sus apariciones plantean una comparación — vinculando profecía con cumplimiento, acción divina con respuesta humana, o un acontecimiento con otro. Todas las traducciones principales convergen en equivalentes comparativos sencillos: como/así como (esp.), comme (fr.), wie (al.). En un caso notable (Hch 15:14), Santiago emplea καθώς no comparativamente sino para introducir un discurso indirecto — «cómo Dios visitó primero» — un uso que el español capta con precisión mediante el interrogativo «cómo».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2532', 'spa', 'Conjunción ''y''; también adverbial ''también, aun, igualmente'' para énfasis o adición', 'La palabra más común del Nuevo Testamento griego, καί es el tejido conectivo básico de la narrativa y el discurso bíblico. Como conjunción copulativa simple encadena cláusulas y listas: ''y Abraham engendró a Isaac, y Isaac engendró a Jacob'' (Mat 1:2). Pero καί también tiene fuerza adverbial significando ''también, aun, igualmente,'' introduciendo a menudo una adición sorprendente o enfática — ''aun los vientos y el mar le obedecen'' (Mat 8:27). Los traductores en todos los idiomas dividen consistentemente estos dos roles: español ''y'' versus ''también'', francés ''et'' versus ''et'' con matiz enfático, alemán ''und'' en ambos pero con distinto peso contextual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2533', 'spa', 'Caifás — el sumo sacerdote judío que presidió el juicio de Jesús y la primera persecución de los apóstoles.', 'Caifás (Καϊάφας) fue el sumo sacerdote durante el ministerio y juicio de Jesús, sirviendo aproximadamente del 18 al 36 d.C. bajo nombramiento romano. Sus nueve apariciones neotestamentarias abarcan los momentos más dramáticos de la narrativa de la Pasión: conspira para arrestar a Jesús (Mt 26:3), preside el juicio judío (Mt 26:57; Jn 18:13-14, 24, 28) y más tarde confronta a los apóstoles (Hch 4:6). El Evangelio de Juan conserva su profecía involuntaria —''conviene que un solo hombre muera por el pueblo'' (Jn 11:49-50)—, que el evangelista interpreta como ironía divinamente inspirada. Lucas lo menciona junto a Anás para datar el inicio del ministerio de Juan el Bautista (Lc 3:2), anclando la narrativa en la cronología histórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2534', 'spa', 'Y en efecto, e incluso (καί con partícula enfática γε); conectivo compuesto con énfasis', 'Compuesto de la conjunción καί («y», «también») con diversas partículas enfáticas u otros conectivos. La expresión καί...γε significa «y en efecto» o «y al menos». Los compuestos relacionados incluyen καὶ δέ («y además»), καὶ δή («y ciertamente», «y de hecho»), y καὶ εἰ (por crasis κεἰ, que significa «y si» o «aun si»). Estas combinaciones añaden matices a la conjunción simple: énfasis, concesión o clímax. Los autores clásicos y bíblicos las emplean para reforzar las conexiones entre cláusulas o para marcar puntos significativos en la argumentación y la narrativa. Cada compuesto tiene su propio matiz, pero todos amplifican la fuerza conectiva básica de καί.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2535', 'spa', 'Caín, el hijo primogénito de Adán que asesinó a su hermano Abel', 'Caín, el primer homicida en la historia bíblica, aparece tres veces en el Nuevo Testamento como ejemplo negativo. Hebreos 11:4 lo menciona implícitamente al señalar que el sacrificio de Abel fue superior al de Caín. Primera Juan 3:12 lo presenta como el arquetipo del malvado: «no como Caín, que era del maligno y mató a su hermano». Judas 11 pronuncia un ay sobre quienes han seguido «el camino de Caín», sendero de celos, homicidio y rechazo de Dios. El nombre hebreo קַיִן posiblemente significa «adquisición» o «lanza». El Nuevo Testamento lo presenta de manera consistente como ejemplo admonitorio: el primero que eligió el mal, mató por envidia y se apartó de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2537', 'spa', 'Nuevo, fresco, sin precedente en su genero — novedad cualitativa distinta de la mera novedad temporal (neos)', 'Nuevo, fresco, sin precedente en su genero — novedad cualitativa distinta de la mera novedad temporal (neos)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2539', 'spa', 'Aunque, a pesar de que; conjunción concesiva usada con participios para expresar contraste o concesión.', 'Esta conjunción concesiva, que significa ''aunque'' o ''a pesar de que'', introduce una declaración que contrasta con lo que cabría esperar. Suele acompañar a un participio. El autor de Hebreos la emplea de manera impactante: Cristo ''aunque era Hijo, aprendió obediencia por lo que padeció'' (Heb 5:8), y Esaú ''aunque la procuró con lágrimas'' no pudo recuperar su primogenitura (Heb 12:17). Pablo la utiliza en Phil 3:4 para conceder que tiene motivos de confianza en la carne. La traducción uniforme al español (''aunque'') confirma su fuerza concesiva directa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2540', 'spa', 'Tiempo señalado, temporada o momento decisivo; punto o período marcado por un propósito divino o relevancia particular.', 'A diferencia de χρόνος, que mide el tiempo cuantitativamente (duración, cronología), καιρός lleva una carga cualitativa: es el tiempo oportuno, el momento propicio, la sazón cargada de significado. En los Evangelios, Jesús habla de ''mi tiempo'' (Mt 26:18) y advierte que los discípulos no conocen los tiempos señalados (Hch 1:7). Pablo lo emplea tanto para la presente era mala como para la venidera ''plenitud de los tiempos''. La palabra transita fluidamente entre un momento señalado en la historia de la salvación, una estación natural o litúrgica, y una ventana de oportunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2541', 'spa', 'César, título del emperador romano reinante, usado en contextos de tributación y judiciales.', 'César, título del emperador romano reinante, usado en contextos de tributación y judiciales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2542', 'spa', 'Cesarea; nombre de ciudad romana que se refiere a Cesarea Marítima (costera) o Cesarea de Filipo (interior). Καισάρεια es el nombre propio de Cesarea,', 'Cesarea; nombre de ciudad romana que se refiere a Cesarea Marítima (costera) o Cesarea de Filipo (interior). Καισάρεια es el nombre propio de Cesarea, que designa dos ciudades distintas en la Palestina romana. Cesarea Marítima, construida por Herodes el Grande en la costa del Mediterráneo, sirvió como capital provincial romana y aparece prominentemente en Hechos como centro de la actividad cristiana primitiva: Felipe se establece allí (Hch 8:40; 21:8), Cornelio recibe a Pedro (Hch 10:1) y Pablo es juzgado ante Félix y Festo (Hch 23:23-25:13). Cesarea de Filipo, al pie del monte Hermón, es donde Pedro confiesa a Jesús como el Cristo (Mt 16:13; Mc 8:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2544', 'spa', 'y sin embargo, aunque; introduce una concesion o contraste', 'Esta conjuncion combina ''y'' (καί) con la particula ''ciertamente'' (τοί), produciendo una fuerza concesiva o contrastiva: ''y sin embargo'', ''aunque''. En Juan 4:2, matiza la afirmacion de que Jesus estaba bautizando: ''aunque (καίτοι) Jesus mismo no bautizaba, sino solo sus discipulos''. La conjuncion introduce una aclaracion o contraste, corrigiendo un posible malentendido. καίτοι reconoce algo mientras introduce una cualificacion que modifica o matiza la declaracion inicial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2545', 'spa', 'Arder, estar en llamas, estar encendido (intransitivo/pasivo); encender, prender (transitivo/causativo). El verbo griego καίω (kaiō) es una de las pal', 'Arder, estar en llamas, estar encendido (intransitivo/pasivo); encender, prender (transitivo/causativo). El verbo griego καίω (kaiō) es una de las palabras elementales de la Escritura: el fuego en forma verbal. Sus apariciones en el NT se dividen entre el estado intransitivo de arder y el acto transitivo de encender. Las lámparas arden en espera del regreso del señor (Lc 12:35), el corazón de los discípulos de Emaús ''ardía dentro de ellos'' mientras Jesús les abría las Escrituras (Lc 24:32), y Juan el Bautista era ''una lámpara que ardía y alumbraba'' (Jn 5:35). En su aspecto más imponente, las ramas son echadas al fuego y ''quemadas'' (Jn 15:6) y el monte Sinaí arde en llamas (Heb 12:18). La única aparición transitiva — ''no se enciende una lámpara para ponerla debajo de un almud'' (Mt 5:15) — desplaza a καίω de describir la llama a causarla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2546', 'spa', 'Y allí, en aquel lugar — adverbio compuesto que combina ''y/también'' con ''allí,'' indicando ubicación. Un adverbio compuesto (καί + ἐκεῖ) que señala un ', 'Y allí, en aquel lugar — adverbio compuesto que combina ''y/también'' con ''allí,'' indicando ubicación. Un adverbio compuesto (καί + ἐκεῖ) que señala un lugar ya establecido en la narración: ''y allí,'' ''en aquel lugar.'' Aparece entretejido en momentos clave de los Evangelios: si recuerdas ante el altar que tu hermano tiene algo contra ti, deja tu ofrenda ''allí'' (Mt 5:23); en cualquier ciudad que entres, quédate ''allí'' (Mt 10:11); Jesús se retiró a una ciudad llamada Efraín y se quedó ''allí'' con sus discípulos (Jn 11:54). Una aparición en Hechos 17:13 lleva un matiz ligeramente aditivo: los agitadores tesalonicenses vinieron ''también allí'' a Berea, subrayando la extensión inesperada de la hostilidad a otra ciudad más.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2547', 'spa', 'Y de allí, y desde allí — adverbio conectivo que une etapas narrativas marcando la partida de un lugar anterior. El adverbio κἀκεῖθεν (kakeithen), una', 'Y de allí, y desde allí — adverbio conectivo que une etapas narrativas marcando la partida de un lugar anterior. El adverbio κἀκεῖθεν (kakeithen), una crasis de καί + ἐκεῖθεν (''y de allí''), funciona como marcador de transición narrativa indicando movimiento de un lugar al siguiente. Enlaza secuencias de itinerario en Hechos y los Evangelios: Jesús parte ''de allí'' en sus viajes por Galilea (Mc 9:30; 10:1), Abraham se desplaza ''de allí'' en el discurso de Esteban (Hch 7:4), y los viajes misioneros de Pablo avanzan ''de allí'' a través de Asia Menor y Grecia (Hch 13:21; 14:26; 16:12; 20:15; 21:1; 27:4; 28:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2548', 'spa', 'Y aquel también, aquellos también; crasis de καί + ἐκεῖνος usada de forma aditiva o como simple conjunción.', 'Y aquel también, aquellos también; crasis de καί + ἐκεῖνος usada de forma aditiva o como simple conjunción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2549', 'spa', 'Maldad de carácter, malicia o perversidad; también problema o dificultad experimentada en la vida cotidiana. En el Nuevo Testamento, κακία denota con ', 'Maldad de carácter, malicia o perversidad; también problema o dificultad experimentada en la vida cotidiana. En el Nuevo Testamento, κακία denota con mayor frecuencia la maldad moral — la disposición de malicia, mala voluntad o perversidad que corrompe el carácter desde adentro. Pablo la incluye en su catálogo de vicios en Romanos 1:29, y Pedro exhorta a los creyentes a desecharla como ropa sucia (1 Pe 2:1). Curiosamente, en Mateo 6:34 Jesús usa la misma palabra para referirse simplemente a ''problema'' o ''dificultad'', las cargas que cada día trae consigo — un uso bien atestiguado en la Septuaginta. La evidencia multilingüe se divide claramente: la mayoría de las lenguas traducen el sentido dominante como ''malicia'' o ''maldad'' (español maldad, alemán Bosheit), mientras que la ocurrencia de Mateo 6:34 atrae traducciones como ''problema'' o ''mal'', señalando un matiz experiencial más que moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2550', 'spa', 'malignidad, malicia, mala intencion; disposicion o caracter perverso', 'Este sustantivo designa una disposicion viciosa o maligna: el deseo activo de perjudicar a otros, no por impulso pasional sino por una mala voluntad arraigada. En Romanos 1:29, aparece en el catalogo paulino de la depravacion humana: llenos de ''envidia, homicidio, contienda, engano, malignidad (κακοηθείας)''. El termino no describe una maldad impulsiva sino una malevolencia calculada, una orientacion habitualmente hostil hacia el projimo. Es perversidad con astucia, la disposicion que se complace en el sufrimiento ajeno y maquina el mal deliberadamente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2551', 'spa', 'Hablar mal de alguien, maldecir, injuriar; abuso verbal dirigido a una persona, especialmente a un padre o autoridad', 'Designa un habla áspera e hiriente dirigida contra alguien: injuriar, maldecir o hablar mal de esa persona. Su uso más notable en el Nuevo Testamento aparece cuando Jesús cita el mandamiento sobre honrar a los padres: ''el que maldiga a su padre o a su madre, morirá irremisiblemente'' (Mt 15:4; Mc 7:10). El peso legal y de pacto del término es evidente en este contexto. En Hch 19:9, los opositores del Camino difaman públicamente la fe ante la congregación, mostrando que el vocablo abarca tanto la maldición formal como el vituperio público.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2552', 'spa', 'sufrimiento, padecimiento; afliccion o penalidad soportada con paciencia', 'Este sustantivo designa la experiencia de adversidad, angustia o sufrimiento, frecuentemente con la implicacion de una resistencia paciente. En Santiago 5:10, los profetas sirven como ''ejemplo de sufrimiento (κακοπαθείας) y de paciencia''. El termino combina ''mal'' o ''adversidad'' con ''experiencia'', describiendo las aflicciones que soportan los fieles. Santiago presenta a los profetas no como modelos de comodidad sino de perseverancia en medio de la angustia: su padecimiento paciente bajo persecucion y rechazo muestra como responder fielmente a las pruebas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2553', 'spa', 'sufrir penalidades, soportar aflicción, padecer dificultades o adversidad', 'Este verbo significa sufrir penalidades, hallarse en angustia o soportar dificultades. Segunda Timoteo lo emplea dos veces en exhortaciones: «Sufro penalidades hasta prisiones» (2:9) y «soporta las aflicciones como buen soldado de Cristo Jesús» (4:5). Santiago 5:13 pregunta pastoralmente: «¿Está afligido alguno entre vosotros? Que ore». El uso clásico incluye estar en mala situación, angustia por circunstancias, enfermedad o incluso plantas que no prosperan. El Nuevo Testamento se centra en soportar la dificultad, especialmente la persecución y aflicción en el ministerio. La palabra enfatiza la perseverancia paciente a través del sufrimiento, no el sufrimiento en sí, sino el sobrellevar activo de la adversidad con fe.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2554', 'spa', 'Hacer el mal, obrar injustamente, causar daño; se contrapone a hacer el bien en el discurso moral', 'Expresa la acción de hacer el mal o causar daño, y aparece constantemente en el Nuevo Testamento como el opuesto moral de hacer el bien. En los relatos sinópticos de una sanación en sábado, Jesús plantea la pregunta incisiva: ''¿Es lícito en sábado hacer el bien o hacer el mal?'' (Mc 3:4; Lc 6:9). El contraste no es abstracto sino concreto: se trata de acciones que dañan o benefician al prójimo. En 1 Pe 3:17, sufrir por hacer el bien se contrasta con sufrir por hacer el mal, y en 3 Jn 1:11 se exhorta a no imitar lo malo sino lo bueno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('G2555', 'spa', 'malhechor, criminal; quien hace el mal o causa daño', 'Este adjetivo usado como sustantivo designa a un malhechor o quien obra el mal, alguien que causa daño o perjuicio. Las tres apariciones se encuentran en 1 Pedro, dentro de su instrucción sobre el sufrimiento. Primera Pedro 2:12 insta a la buena conducta entre los gentiles para que, cuando calumnien a los creyentes «como malhechores», queden desmentidos por las obras visiblemente buenas. En 2:14 describe al gobierno como quien castiga a «los malhechores» y alaba a quienes hacen el bien. En 4:15 advierte a los creyentes que no sufran como asesinos, ladrones ni «malhechores». Pedro emplea el término tanto para la falsa acusación contra los cristianos como para quienes realmente merecen castigo.');